"use client";

import { useEffect, useMemo, useRef, useState, type Dispatch, type SetStateAction } from "react";
import type { AssistantSettings, BrandSettings, ContentItem, CEOMessageContent, FooterContent, HomepageBand, HomepageBandId, HomepageContent, Locale, MediaAsset, SiteData, TrashItem } from "@company/contracts";
import { localeLabels } from "@company/contracts";
import { AdminThemeProvider, useAdminTheme } from "./AdminTheme";

const API = process.env.NEXT_PUBLIC_ADMIN_API_BASE_URL || "http://localhost:4000";
const PUBLIC = process.env.NEXT_PUBLIC_PUBLIC_SITE_URL || "http://localhost:3000";
const BRAND_MARK_PATH = "/branding/movera-mark.svg";
const BRAND_WORDMARK_PATH = "/branding/movera-wordmark.svg";
const BRAND_SOURCE_PATH = "/admin-branding/movera-logo-source.png";
type Workspace = "editor" | "users" | "trash" | "settings";
type Role = "Super Admin" | "Content Editor" | "Publisher" | "User Manager" | "Viewer";
const roles: Role[] = ["Super Admin", "Content Editor", "Publisher", "User Manager", "Viewer"];
const contentSections: ContentItem["type"][] = ["pages", "services", "products", "projects", "news", "blogs", "jobs", "innovation"];
const labels: Record<ContentItem["type"], string> = { news: "News", blogs: "Blogs", projects: "Projects", services: "Services", products: "Products", pages: "About pages", jobs: "Careers", innovation: "Innovation Hub" };
const contentSectionOptions = contentSections.map(value => ({ value, label: labels[value] }));
const roleOptions = roles.map(value => ({ value, label: value }));
const publicRoute = (type: ContentItem["type"]) => type === "pages" ? "about" : type === "jobs" ? "careers" : type === "innovation" ? "innovation-hub" : type;
const publicUrl = (type: ContentItem["type"], locale: Locale, slug?: string) => `${PUBLIC}/${locale}/${publicRoute(type)}${slug ? `/${encodeURIComponent(slug)}` : ""}`;
const emptyLocale = (): Record<Locale, string> => ({ en: "", ar: "", fr: "", nl: "" });
const emptyItem = (type: ContentItem["type"]): ContentItem => ({ id: "", type, slug: emptyLocale(), title: emptyLocale(), summary: emptyLocale(), body: emptyLocale(), featured: false, status: "draft", tags: [] });
const copy = <T,>(value: T): T => structuredClone(value);

type User = { id: string; name: string; email: string; role: Role; active: boolean; forcePasswordReset: boolean; lastLoginAt: string | null; createdAt: string };
type EditableDocument = ContentItem | CEOMessageContent;
const isCEOMessage = (value: EditableDocument | null): value is CEOMessageContent => Boolean(value && "message" in value);

async function api(path: string, init: RequestInit = {}) {
  const headers = new Headers(init.headers);
  if (init.body && !(init.body instanceof FormData) && !headers.has("content-type")) headers.set("content-type", "application/json");
  return fetch(`${API}${path}`, { ...init, headers, credentials: "include" });
}

function AdminBrandAsset({ kind, media, alt }: { kind: "mark" | "wordmark"; media?: MediaAsset; alt: string }) {
  const suppliedMOVERAAsset = media?.url?.includes("/branding/movera-mark.svg") || media?.url?.includes("/branding/movera-wordmark.svg");
  if (suppliedMOVERAAsset) return <span className={`admin-brand-asset-crop admin-brand-asset-crop--${kind}`}><img className="admin-brand-source-image" src={BRAND_SOURCE_PATH} alt={alt} /></span>;
  return <img className={kind === "mark" ? "admin-brand-mark" : "admin-brand-wordmark"} {...optimizedMediaProps(media, `${PUBLIC}${kind === "mark" ? BRAND_MARK_PATH : BRAND_WORDMARK_PATH}`)} alt={alt} />;
}

function AdminBrand() {
  const { theme } = useAdminTheme();
  const [brand, setBrand] = useState<Partial<BrandSettings> | null>(null);
  useEffect(() => {
    fetch(`${API}/api/v1/site`)
      .then(response => response.ok ? response.json() : Promise.reject())
      .then(payload => { if (payload.data?.brand) setBrand(payload.data.brand); })
      .catch(() => undefined);
  }, []);
  const wordmarkText = brand?.wordmarkText?.en?.trim() || "MOVERA";
  const useEditableWordmark = wordmarkText.toLocaleUpperCase() !== "MOVERA";
  const mark = theme === "light" ? brand?.markLight || brand?.mark : brand?.markDark || brand?.mark;
  const wordmark = theme === "light" ? brand?.wordmarkLight || brand?.wordmark : brand?.wordmarkDark || brand?.wordmark;
  return <span className="admin-brand-lockup" aria-label="MOVERA">
    <AdminBrandAsset kind="mark" media={mark} alt="MOVERA mark" />
    {useEditableWordmark ? <span className="admin-brand-wordmark-text">{wordmarkText}</span> : <AdminBrandAsset kind="wordmark" media={wordmark} alt="MOVERA" />}
  </span>;
}

export function AdminApp() {
  const [user, setUser] = useState<User | null>(null);
  const [booting, setBooting] = useState(true);
  const [loginError, setLoginError] = useState("");
  const checkSession = async () => { try { const response = await api("/api/v1/admin/auth/me"); if (response.ok) setUser((await response.json()).data.user); } finally { setBooting(false); } };
  useEffect(() => { void checkSession(); }, []);
  return <AdminThemeProvider>{booting ? <LoadingScreen /> : !user ? <LoginScreen onSuccess={setUser} error={loginError} setError={setLoginError} /> : <AdminShell user={user} setUser={setUser} />}</AdminThemeProvider>;
}

function LoadingScreen() { return <div className="admin-loading"><AdminBrand /><p>Loading MOVERA CMS</p></div>; }

function LoginScreen({ onSuccess, error, setError }: { onSuccess: (user: User) => void; error: string; setError: (value: string) => void }) {
  const [email, setEmail] = useState("admin@movera.local");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const response = await api("/api/v1/admin/auth/login", { method: "POST", body: JSON.stringify({ email, password }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error?.code === "INVALID_CREDENTIALS" ? "The email or password is not valid." : "Unable to sign in."); onSuccess(payload.data.user); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to sign in."); } finally { setBusy(false); } };
  return <main className="login-screen"><div className="login-glow" /><section className="login-panel"><div className="brand-lockup"><AdminBrand /></div><p className="eyebrow">Secure workspace</p><h1>Welcome back.</h1><p className="login-copy">Manage approved content, access, and publishing workflows from one controlled workspace.</p><form onSubmit={submit}><label className="field"><span>Email</span><input type="email" value={email} onChange={event => setEmail(event.target.value)} autoComplete="username" required /></label><label className="field"><span>Password</span><input type="password" value={password} onChange={event => setPassword(event.target.value)} autoComplete="current-password" required /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary-action" disabled={busy}>{busy ? "Signing in…" : "Sign in"}<span>→</span></button></form><p className="login-foot">Local authentication is protected by server-side sessions. Entra ID can be enabled by a Super Admin.</p></section></main>;
}

function AdminShell({ user, setUser }: { user: User; setUser: (user: User | null) => void }) {
  const [workspace, setWorkspace] = useState<Workspace>("editor");
  const [notice, setNotice] = useState("Ready");
  const logout = async () => { await api("/api/v1/admin/auth/logout", { method: "POST" }); setUser(null); };
  const nav: Array<{ id: Workspace; label: string; icon: string }> = [{ id: "editor", label: "Content Editor", icon: "✦" }, { id: "users", label: "User Management", icon: "◎" }, ...(user.role === "Super Admin" ? [{ id: "trash" as const, label: "Trash", icon: "♻" }] : []), { id: "settings", label: "Settings", icon: "◌" }];
  return <div className="admin-shell"><aside className="admin-sidebar"><div className="admin-brand"><AdminBrand /></div><div className="side-kicker">Workspace</div><nav>{nav.map(item => <button key={item.id} className={workspace === item.id ? "active" : ""} onClick={() => setWorkspace(item.id)}><span>{item.icon}</span>{item.label}</button>)}</nav><div className="account"><div className="avatar">{user.name.slice(0, 1)}</div><div><strong>{user.name}</strong><small>{user.role}</small></div><button onClick={logout} aria-label="Sign out">↗</button></div></aside><main className="admin-main"><header className="admin-header"><div><p className="eyebrow">MOVERA / CMS</p><h1>{nav.find(item => item.id === workspace)?.label}</h1></div><div className="header-right"><span className="notice"><i />{notice}</span><a href={`${PUBLIC}/en`} target="_blank" rel="noreferrer" className="public-link">Open public site ↗</a></div></header>{workspace === "editor" && <EnhancedContentEditor setNotice={setNotice} user={user} />}{workspace === "users" && <UserManagement setNotice={setNotice} user={user} />}{workspace === "trash" && <TrashWorkspace setNotice={setNotice} />}{workspace === "settings" && <SettingsWorkspace setNotice={setNotice} user={user} />}</main></div>;
}

function LocaleTabs({ locale, setLocale }: { locale: Locale; setLocale: (locale: Locale) => void }) { return <div className="locale-tabs" role="tablist">{(Object.keys(localeLabels) as Locale[]).map(item => <button role="tab" aria-selected={locale === item} className={locale === item ? "active" : ""} onClick={() => setLocale(item)} key={item}>{localeLabels[item]}</button>)}</div>; }
function Field({ label, value, onChange, multiline = false, hint }: { label: string; value: string; onChange: (value: string) => void; multiline?: boolean; hint?: string }) { return <label className="field"><span>{label}</span>{multiline ? <textarea value={value} onChange={event => onChange(event.target.value)} rows={4} /> : <input value={value} onChange={event => onChange(event.target.value)} />}{hint && <small>{hint}</small>}</label>; }

function mediaWithUrl(media: MediaAsset | undefined, id: string, url: string): MediaAsset | undefined {
  if (!url.trim()) return undefined;
  return { id: media?.id || id, url: url.trim(), alt: media?.alt || emptyLocale(), caption: media?.caption, credit: media?.credit, focalX: media?.focalX ?? 50, focalY: media?.focalY ?? 50, zoom: media?.zoom ?? 1 };
}

function publicMediaUrl(url?: string) {
  if (!url) return "";
  return url.startsWith("/") && !url.startsWith("//") ? `${PUBLIC}${url}` : "";
}

function optimizedMediaProps(media: MediaAsset | undefined, fallback: string) {
  const variants = [...(media?.variants || [])].filter(variant => variant.url.startsWith("/") && !variant.url.startsWith("//") && variant.width).sort((left, right) => left.width - right.width);
  const optimizedFallback = fallback;
  return {
    src: publicMediaUrl(variants[variants.length - 1]?.url || media?.url) || optimizedFallback,
    ...(variants.length ? {
      srcSet: variants.map(variant => `${publicMediaUrl(variant.url)} ${variant.width}w`).join(", "),
      sizes: "(max-width: 760px) 100vw, 640px",
    } : {}),
  };
}

function uploadedMedia(data: MediaAsset, existing?: MediaAsset): MediaAsset {
  return {
    ...(existing || {}),
    id: data.id,
    url: data.url,
    alt: existing?.alt || emptyLocale(),
    width: data.width,
    height: data.height,
    mimeType: data.mimeType,
    sizeBytes: data.sizeBytes,
    variants: data.variants,
  };
}

function MediaSlotEditor({ label, locale, media, fallback, onChange, onUpload }: { label: string; locale: Locale; media?: MediaAsset; fallback: string; onChange: (media?: MediaAsset) => void; onUpload: (file: File) => Promise<void> }) {
  return <div className="structured-media-slot"><div className="media-large"><img className="media-preview-image" {...optimizedMediaProps(media, fallback)} alt={media?.alt?.[locale] || label} /><span>{media ? "Published image" : "Default image"}</span></div><div className="media-fields"><Field label={`${label} URL`} value={media?.url || ""} onChange={value => onChange(mediaWithUrl(media, `${label.toLowerCase().replaceAll(" ", "-")}-image`, value))} hint="Use the installed image URL or upload a replacement." /><Field label={`Alt text · ${localeLabels[locale]}`} value={media?.alt?.[locale] || ""} onChange={value => { if (!media) return; onChange({ ...media, alt: { ...media.alt, [locale]: value } }); }} /><Field label={`Caption · ${localeLabels[locale]}`} value={media?.caption?.[locale] || ""} onChange={value => { if (!media) return; onChange({ ...media, caption: { ...(media.caption || emptyLocale()), [locale]: value } }); }} hint="Shown below the image when it is opened full size." /><label className="upload-control"><span>Upload replacement</span><b>Browse files</b><input type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/avif" onChange={event => { const file = event.target.files?.[0]; if (file) void onUpload(file); }} /></label></div></div>;
}

function MediaGalleryEditor({ locale, gallery, onChange }: { locale: Locale; gallery?: NonNullable<ContentItem["gallery"]>; onChange: (gallery: NonNullable<ContentItem["gallery"]>) => void }) {
  const update = (index: number, patch: Partial<MediaAsset>) => onChange((gallery || []).map((asset, assetIndex) => assetIndex === index ? { ...asset, ...patch } : asset));
  const add = () => onChange([...(gallery || []), { id: `gallery-${Date.now()}`, url: "", alt: emptyLocale(), caption: emptyLocale(), focalX: 50, focalY: 50 }]);
  return <div className="media-gallery-editor"><div className="structured-group-heading"><strong>Gallery images and captions</strong><button type="button" className="secondary-action compact" onClick={add}>Add image</button></div>{(gallery || []).map((asset, index) => <article className="media-gallery-row" key={asset.id || index}><div className="media-gallery-row-head"><strong>Image {String(index + 1).padStart(2, "0")}</strong><button type="button" className="danger-action compact" onClick={() => onChange((gallery || []).filter((_, assetIndex) => assetIndex !== index))}>Remove</button></div><Field label="Image URL" value={asset.url} onChange={value => update(index, { url: value })} /><Field label={`Alt text · ${localeLabels[locale]}`} value={asset.alt?.[locale] || ""} onChange={value => update(index, { alt: { ...asset.alt, [locale]: value } })} /><Field label={`Caption · ${localeLabels[locale]}`} value={asset.caption?.[locale] || ""} onChange={value => update(index, { caption: { ...(asset.caption || emptyLocale()), [locale]: value } })} /></article>)}{!(gallery || []).length && <p className="structured-empty">No gallery images yet. Add one to make its caption editable.</p>}</div>;
}

function BrandingSettingsPanel({ brand, setBrand, uploadBrand, saveBrand, footer, setFooter, saveFooter, canManage }: { brand: BrandSettings; setBrand: (value: BrandSettings) => void; uploadBrand: (key: BrandMediaKey, file: File) => Promise<void>; saveBrand: () => Promise<void>; footer: FooterContent; setFooter: (value: FooterContent) => void; saveFooter: () => Promise<void>; canManage: boolean }) {
  const setMedia = (key: BrandMediaKey, media?: MediaAsset) => { if (media) setBrand({ ...brand, [key]: media }); };
  return <section className="settings-panel"><div className="panel-title"><span className="panel-icon">▣</span><div><h3>Website branding</h3><p>Use the supplied MOVERA mark and wordmark on the fixed light presentation.</p></div></div>
    <div className="branding-media-grid">
      <MediaSlotEditor label="Mark · default" locale="en" media={brand.mark} fallback={`${PUBLIC}${BRAND_MARK_PATH}`} onChange={media => setMedia("mark", media)} onUpload={file => uploadBrand("mark", file)} />
      <MediaSlotEditor label="Wordmark · default" locale="en" media={brand.wordmark} fallback={`${PUBLIC}${BRAND_WORDMARK_PATH}`} onChange={media => setMedia("wordmark", media)} onUpload={file => uploadBrand("wordmark", file)} />
      <MediaSlotEditor label="Mark · light presentation" locale="en" media={brand.markLight} fallback={`${PUBLIC}${BRAND_MARK_PATH}`} onChange={media => setMedia("markLight", media)} onUpload={file => uploadBrand("markLight", file)} />
      <MediaSlotEditor label="Wordmark · light presentation" locale="en" media={brand.wordmarkLight} fallback={`${PUBLIC}${BRAND_WORDMARK_PATH}`} onChange={media => setMedia("wordmarkLight", media)} onUpload={file => uploadBrand("wordmarkLight", file)} />
    </div>
    <div className="settings-form-grid"><Field label="Logo text · English" value={brand.wordmarkText.en} onChange={value => setBrand({ ...brand, wordmarkText: { ...brand.wordmarkText, en: value } })} hint="Leave MOVERA to use the supplied wordmark image. A different value is rendered as editable text." /><Field label="Logo text · العربية" value={brand.wordmarkText.ar} onChange={value => setBrand({ ...brand, wordmarkText: { ...brand.wordmarkText, ar: value } })} /><Field label="Logo text · Français" value={brand.wordmarkText.fr} onChange={value => setBrand({ ...brand, wordmarkText: { ...brand.wordmarkText, fr: value } })} /><Field label="Logo text · Nederlands" value={brand.wordmarkText.nl} onChange={value => setBrand({ ...brand, wordmarkText: { ...brand.wordmarkText, nl: value } })} /></div><div className="setting-actions"><button className="primary-action compact" onClick={() => void saveBrand()} disabled={!canManage}>Save branding <span>→</span></button></div><div className="settings-nested-panel"><div className="panel-title"><span className="panel-icon">◎</span><div><h3>Footer social links</h3><p>Manage the public social destinations. Empty URLs hide that platform’s icon; social destinations intentionally open in a new tab.</p></div></div><div className="settings-form-grid"><Field label="Facebook URL" value={footer.socialLinks.facebook} onChange={value => setFooter({ ...footer, socialLinks: { ...footer.socialLinks, facebook: value } })} /><Field label="Instagram URL" value={footer.socialLinks.instagram} onChange={value => setFooter({ ...footer, socialLinks: { ...footer.socialLinks, instagram: value } })} /><Field label="YouTube URL" value={footer.socialLinks.youtube} onChange={value => setFooter({ ...footer, socialLinks: { ...footer.socialLinks, youtube: value } })} /><Field label="LinkedIn URL" value={footer.socialLinks.linkedin} onChange={value => setFooter({ ...footer, socialLinks: { ...footer.socialLinks, linkedin: value } })} /></div><div className="setting-actions"><button className="primary-action compact" onClick={() => void saveFooter()} disabled={!canManage}>Save social links <span>→</span></button></div></div></section>;
}

function previewUrl(item: ContentItem) {
  return publicMediaUrl(item.cover?.url || item.sections?.find(section => section.media)?.media?.url || item.timeline?.find(entry => entry.media)?.media?.url || item.profiles?.find(profile => profile.portrait)?.portrait?.url || item.credentials?.find(credential => credential.media)?.media?.url) || `${PUBLIC}/starter-media/movera-hero-field.svg`;
}

type PickerOption<T extends string> = { value: T; label: string };

function AdminSelect<T extends string>({ value, options, onChange, ariaLabel }: { value: T; options: PickerOption<T>[]; onChange: (value: T) => void; ariaLabel: string }) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const closeOnOutside = (event: PointerEvent) => { if (root.current && event.target instanceof Node && !root.current.contains(event.target)) setOpen(false); };
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") setOpen(false); };
    document.addEventListener("pointerdown", closeOnOutside);
    document.addEventListener("keydown", closeOnEscape);
    return () => { document.removeEventListener("pointerdown", closeOnOutside); document.removeEventListener("keydown", closeOnEscape); };
  }, [open]);
  const selected = options.find(option => option.value === value);
  return <div className="template-picker admin-select" ref={root}>
    <button type="button" className="template-picker-trigger" aria-haspopup="listbox" aria-expanded={open} aria-label={ariaLabel} onClick={() => setOpen(current => !current)}><span>{ariaLabel}</span><strong>{selected?.label || "Choose an option"}</strong><span className="template-picker-chevron">⌄</span></button>
    {open && <div className="template-picker-menu" role="listbox" aria-label={ariaLabel}>{options.map(option => <button type="button" role="option" aria-selected={option.value === value} className={option.value === value ? "selected" : ""} key={option.value} onClick={() => { onChange(option.value); setOpen(false); }}>{option.label}<span>{option.value === value ? "✓" : ""}</span></button>)}</div>}
  </div>;
}

function ContentEditor({ setNotice, user }: { setNotice: (value: string) => void; user: User }) {
  const [site, setSite] = useState<SiteData | null>(null);
  const [type, setType] = useState<ContentItem["type"]>("projects");
  const [locale, setLocale] = useState<Locale>("en");
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState<ContentItem | null>(null);
  const [savedSnapshot, setSavedSnapshot] = useState<ContentItem | null>(null);
  const [undoStack, setUndoStack] = useState<ContentItem[]>([]);
  const [redoStack, setRedoStack] = useState<ContentItem[]>([]);
  const [preview, setPreview] = useState(false);
  const canEdit = user.role !== "Viewer";
  const canPublish = user.role === "Super Admin" || user.role === "Publisher";
  useEffect(() => { api("/api/v1/admin/site").then(response => response.json()).then(payload => setSite(payload.data)).catch(() => setNotice("The content API is unavailable")); }, [setNotice]);
  const items = useMemo(() => (site?.[type] || []).filter(item => `${item.title.en} ${item.title.ar} ${item.title.fr} ${item.title.nl}`.toLowerCase().includes(query.toLowerCase())), [site, type, query]);
  const startEdit = (item: ContentItem) => { const next = copy(item); setEditing(next); setSavedSnapshot(copy(next)); setUndoStack([]); setRedoStack([]); };
  const update = (next: ContentItem) => { if (!editing) return; setUndoStack(stack => [...stack.slice(-19), copy(editing)]); setRedoStack([]); setEditing(next); };
  const updateLocalized = (field: "title" | "slug" | "summary" | "body", value: string) => { if (!editing) return; update({ ...editing, [field]: { ...editing[field], [locale]: value } }); };
  const undo = () => { if (!editing || undoStack.length === 0) return; const previous = undoStack[undoStack.length - 1]; setUndoStack(stack => stack.slice(0, -1)); setRedoStack(stack => [...stack, copy(editing)]); setEditing(previous); };
  const redo = () => { if (!editing || redoStack.length === 0) return; const next = redoStack[redoStack.length - 1]; setRedoStack(stack => stack.slice(0, -1)); setUndoStack(stack => [...stack, copy(editing)]); setEditing(next); };
  const reset = () => { if (savedSnapshot) { setEditing(copy(savedSnapshot)); setUndoStack([]); setRedoStack([]); setNotice("Unsaved changes reset to the last saved version"); } };
  const save = async () => { if (!editing || !canEdit) return; setNotice("Saving draft…"); const method = editing.id ? "PUT" : "POST"; const path = editing.id ? `/api/v1/content/${type}/${editing.id}` : `/api/v1/content/${type}`; const response = await api(path, { method, body: JSON.stringify({ ...editing, status: "draft" }) }); const payload = await response.json(); if (!response.ok) { setNotice("Draft could not be saved"); return; } const nextItem = payload.data as ContentItem; setSite(current => current ? { ...current, [type]: editing.id ? current[type].map(item => item.id === nextItem.id ? nextItem : item) : [nextItem, ...current[type]] } : current); setEditing(copy(nextItem)); setSavedSnapshot(copy(nextItem)); setUndoStack([]); setRedoStack([]); setNotice("Draft saved"); };
  const lifecycle = async (status: "published" | "archived" | "draft") => { if (!editing || !canPublish) return; setNotice(status === "published" ? "Publishing…" : status === "archived" ? "Archiving…" : "Restoring…"); const response = await api(`/api/v1/admin/content/${type}/${editing.id}/status`, { method: "PATCH", body: JSON.stringify({ status }) }); const payload = await response.json(); if (!response.ok) { setNotice("Action not permitted"); return; } setEditing(copy(payload.data)); setSavedSnapshot(copy(payload.data)); setSite(current => current ? { ...current, [type]: current[type].map(item => item.id === editing.id ? payload.data : item) } : current); setNotice(status === "published" ? "Published · news bar updated" : status === "archived" ? "Archived from the public site" : "Restored as a draft"); };
  const remove = async () => { if (!editing || user.role !== "Super Admin") return; if (!window.confirm("Move this content to Trash? You can restore it later from the Trash workspace.")) return; const response = await api(`/api/v1/content/${type}/${editing.id}`, { method: "DELETE" }); if (!response.ok) { setNotice("Content could not be moved to Trash"); return; } setSite(current => current ? { ...current, [type]: current[type].filter(item => item.id !== editing.id) } : current); setEditing(null); setSavedSnapshot(null); setNotice("Content moved to Trash"); };
  const upload = async (file: File) => { const form = new FormData(); form.append("file", file); setNotice("Uploading media…"); const response = await api("/api/v1/media", { method: "POST", body: form }); const payload = await response.json(); if (response.ok && editing) { update({ ...editing, cover: uploadedMedia(payload.data as MediaAsset, editing.cover) }); setNotice("Media uploaded"); } else setNotice(payload.error?.message || "Media upload failed"); };
  if (!site) return <div className="workspace-loading">Loading content workspace…</div>;
  return <div className="workspace"><div className="editor-toolbar"><div className="select-stack"><AdminSelect value={type} options={contentSectionOptions} ariaLabel="Page template" onChange={value => { setType(value); setEditing(null); }} /><div className="search-control"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder={`Search ${labels[type].toLowerCase()}`} /></div></div><div className="toolbar-meta"><span className="locked-pill">Design system locked</span><a href={publicUrl(type, "en")} target="_blank" rel="noreferrer">View collection ↗</a></div></div><div className="editor-layout"><section className="content-index"><div className="index-head"><div><p className="eyebrow">Structured content</p><h2>{labels[type]}</h2></div>{canEdit && <button className="secondary-action" onClick={() => startEdit(emptyItem(type))}>New {type === "news" ? "item" : labels[type].replace(/s$/, "")}</button>}</div><p className="section-copy">Select a page to edit approved content fields. Publishing, archival, and restoration are tracked actions.</p><div className="content-list">{items.map(item => <button className={`content-entry ${editing?.id === item.id ? "selected" : ""}`} key={item.id} onClick={() => startEdit(item)}><span className="entry-thumb"><img {...optimizedMediaProps(item.cover, publicMediaUrl(item.cover?.url) || `${PUBLIC}/starter-media/movera-hero-field.svg`)} alt="" loading="lazy" /></span><span className="entry-copy"><strong>{item.title.en || "Untitled content"}</strong><small>{item.slug.en || "No English slug"}</small></span><span className={`status-tag ${item.status || "published"}`}>{item.status || "published"}</span><span className="entry-arrow">→</span></button>)}{items.length === 0 && <div className="empty-state">No matching content.</div>}</div></section>{editing ? <section className="editor-pane"><div className="pane-head"><div><p className="eyebrow">Edit mode · {labels[type]}</p><h2>{editing.title.en || "Untitled content"}</h2></div><div className="pane-actions"><button className="icon-action" onClick={undo} disabled={!undoStack.length} title="Undo">↶ Undo</button><button className="icon-action" onClick={redo} disabled={!redoStack.length} title="Redo">↷ Redo</button><button className="text-action" onClick={reset}>Reset to default</button><button className="text-action" onClick={() => setPreview(value => !value)}>{preview ? "Edit fields" : "Preview page"}</button></div></div>{preview ? <div className="preview-frame"><iframe title="Public page preview" src={publicUrl(type, locale, editing.slug[locale] || editing.slug.en)} /><div className="preview-lock">Preview uses the public renderer · layout remains locked</div></div> : <><div className="editor-locales"><LocaleTabs locale={locale} setLocale={setLocale} /><span>{locale === "ar" ? "RTL content editing" : "Native content locale"}</span></div><div className="editable-surface" dir={locale === "ar" ? "rtl" : "ltr"}><div className="field-grid"><Field label="Title" value={editing.title[locale]} onChange={value => updateLocalized("title", value)} /><Field label="Slug" value={editing.slug[locale]} onChange={value => updateLocalized("slug", value)} hint="Used in this locale only" /><Field label="Summary" value={editing.summary[locale]} onChange={value => updateLocalized("summary", value)} multiline /><Field label="Body" value={editing.body[locale]} onChange={value => updateLocalized("body", value)} multiline /><Field label="AI capability / category" value={editing.category || editing.sector || ""} onChange={value => update({ ...editing, category: value, sector: value })} /><Field label="Tags" value={(editing.tags || []).join(", ")} onChange={value => update({ ...editing, tags: value.split(",").map(tag => tag.trim()).filter(Boolean) })} /></div><div className="media-editor"><div><p className="eyebrow">Approved media slot</p><h3>Cover image</h3><p>Replace the media without changing the frame, typography, or page composition.</p></div><div className="media-edit-grid"><div className="media-large"><img className="media-preview-image" {...optimizedMediaProps(editing.cover, `${PUBLIC}/starter-media/movera-hero-field.svg`)} alt={editing.cover?.alt?.en || editing.title.en || "Published content image"} style={{ objectPosition: `${editing.cover?.focalX ?? 50}% ${editing.cover?.focalY ?? 50}%` }} /><span>{editing.cover ? "Published cover image" : "Default approved image"}</span></div><div className="media-fields"><Field label="Image URL" value={editing.cover?.url || ""} onChange={value => update({ ...editing, cover: value ? { id: editing.cover?.id || `${editing.id || "new"}-cover`, url: value, alt: editing.cover?.alt || emptyLocale(), focalX: editing.cover?.focalX ?? 50, focalY: editing.cover?.focalY ?? 50 } : undefined })} /><label className="upload-control"><span>Replace image</span><b>Browse files</b><input type="file" accept="image/png,image/jpeg,image/webp,image/avif" onChange={event => { const file = event.target.files?.[0]; if (file) void upload(file); }} /></label><label className="field"><span>Crop / focal point</span><input type="range" min="0" max="100" value={editing.cover?.focalX ?? 50} onChange={event => update({ ...editing, cover: editing.cover ? { ...editing.cover, focalX: Number(event.target.value) } : undefined })} /></label><MediaGalleryEditor locale={locale} gallery={editing.gallery} onChange={gallery => update({ ...editing, gallery })} /></div></div></div></div><div className="save-rail"><span>Changes are scoped to {localeLabels[locale]} only.</span><div><button className="secondary-action" onClick={() => setEditing(null)}>Close</button><button className="primary-action compact" onClick={save} disabled={!canEdit}>Save draft <span>→</span></button>{canPublish && editing.id && type !== "pages" && <>{editing.status === "archived" ? <button className="secondary-action" onClick={() => void lifecycle("draft")}>Restore</button> : <button className="publish-action" onClick={() => void lifecycle(editing.status === "published" || !editing.status ? "archived" : "published")}>{editing.status === "published" || !editing.status ? "Archive" : "Publish"}</button>}{user.role === "Super Admin" && editing.status && <button className="danger-action" onClick={() => void remove()}>Delete</button>}</>}</div></div></>}</section> : <div className="empty-editor"><div className="empty-orbit">✦</div><h2>Choose a page to edit</h2><p>The public renderer stays visible in Preview, while editable fields remain limited to approved content regions.</p></div>}</div></div>;
}

function ReorderControls({ index, length, onMove }: { index: number; length: number; onMove: (direction: -1 | 1) => void }) {
  return <span className="structured-order-actions" aria-label="Reorder item">
    <button type="button" className="secondary-action compact" onClick={() => onMove(-1)} disabled={index === 0} aria-label="Move up">↑</button>
    <button type="button" className="secondary-action compact" onClick={() => onMove(1)} disabled={index === length - 1} aria-label="Move down">↓</button>
  </span>;
}

function moveAt<T,>(values: T[] | undefined, index: number, direction: -1 | 1) {
  if (!values) return values;
  const nextIndex = index + direction;
  if (nextIndex < 0 || nextIndex >= values.length) return values;
  const next = [...values];
  [next[index], next[nextIndex]] = [next[nextIndex], next[index]];
  return next;
}

function StructuredContentFields({ item, locale, update, uploadMedia }: { item: ContentItem; locale: Locale; update: (next: ContentItem) => void; uploadMedia: (file: File, apply: (asset: MediaAsset) => void) => Promise<void> }) {
  const updateSection = (index: number, patch: Partial<NonNullable<ContentItem["sections"]>[number]>) => update({ ...item, sections: item.sections?.map((entry, entryIndex) => entryIndex === index ? { ...entry, ...patch } : entry) });
  const updateTimeline = (index: number, patch: Partial<NonNullable<ContentItem["timeline"]>[number]>) => update({ ...item, timeline: item.timeline?.map((entry, entryIndex) => entryIndex === index ? { ...entry, ...patch } : entry) });
  const updateProfile = (index: number, patch: Partial<NonNullable<ContentItem["profiles"]>[number]>) => update({ ...item, profiles: item.profiles?.map((entry, entryIndex) => entryIndex === index ? { ...entry, ...patch } : entry) });
  const updateCredential = (index: number, patch: Partial<NonNullable<ContentItem["credentials"]>[number]>) => update({ ...item, credentials: item.credentials?.map((entry, entryIndex) => entryIndex === index ? { ...entry, ...patch } : entry) });
  const updateBullets = (values: Array<Record<string, string>> | undefined, value: string) => value.split("\n").map((line, index) => ({ ...emptyLocale(), ...(values?.[index] || {}), [locale]: line })).filter(entry => entry[locale].trim());
  const addSection = () => update({ ...item, sections: [...(item.sections || []), { id: `section-${Date.now()}`, eyebrow: emptyLocale(), title: emptyLocale(), body: emptyLocale(), bullets: [] }] });
  const addTimeline = () => update({ ...item, timeline: [...(item.timeline || []), { id: `timeline-${Date.now()}`, label: emptyLocale(), title: emptyLocale(), body: emptyLocale() }] });
  const addProfile = () => update({ ...item, profiles: [...(item.profiles || []), { id: `profile-${Date.now()}`, name: emptyLocale(), role: emptyLocale(), summary: emptyLocale() }] });
  const addCredential = () => update({ ...item, credentials: [...(item.credentials || []), { id: `credential-${Date.now()}`, title: emptyLocale(), issuer: emptyLocale(), description: emptyLocale() }] });
  const removeAt = <T,>(values: T[] | undefined, index: number) => values?.filter((_, entryIndex) => entryIndex !== index);
  return <section className="structured-editor"><div className="structured-editor-heading"><div><p className="eyebrow">Structured page content</p><h3>Visible sections, text, and images</h3></div><span>These fields feed the current public layout.</span></div>
    {(item.aboutLayout === "story" || item.aboutLayout === "vision" || item.sections) && <div className="structured-group-heading"><strong>Sections</strong><button type="button" className="secondary-action compact" onClick={addSection}>Add section</button></div>}
    {item.sections?.map((entry, index) => <article className="structured-card" key={entry.id}><div className="structured-card-heading"><strong>Section {String(index + 1).padStart(2, "0")}</strong><span>{entry.id}</span><ReorderControls index={index} length={item.sections?.length || 0} onMove={direction => update({ ...item, sections: moveAt(item.sections, index, direction) })} /><button type="button" className="danger-action compact" onClick={() => update({ ...item, sections: removeAt(item.sections, index) })}>Remove</button></div><div className="field-grid"><Field label="Eyebrow" value={entry.eyebrow?.[locale] || ""} onChange={value => updateSection(index, { eyebrow: { ...(entry.eyebrow || emptyLocale()), [locale]: value } })} /><Field label="Title" value={entry.title[locale]} onChange={value => updateSection(index, { title: { ...entry.title, [locale]: value } })} /><Field label="Body" value={entry.body[locale]} onChange={value => updateSection(index, { body: { ...entry.body, [locale]: value } })} multiline /><Field label="Bullets · one per line" value={(entry.bullets || []).map(bullet => bullet[locale]).join("\n")} onChange={value => updateSection(index, { bullets: updateBullets(entry.bullets, value) })} multiline /></div><MediaSlotEditor label="Section image" locale={locale} media={entry.media} fallback={`${PUBLIC}/starter-media/movera-hero-field.svg`} onChange={media => updateSection(index, { media })} onUpload={file => uploadMedia(file, asset => updateSection(index, { media: asset }))} /></article>)}
    {(item.aboutLayout === "timeline" || item.timeline) && <div className="structured-group-heading"><strong>Timeline</strong><button type="button" className="secondary-action compact" onClick={addTimeline}>Add timeline entry</button></div>}
    {item.timeline?.map((entry, index) => <article className="structured-card" key={entry.id}><div className="structured-card-heading"><strong>Timeline entry {String(index + 1).padStart(2, "0")}</strong><span>{entry.id}</span><ReorderControls index={index} length={item.timeline?.length || 0} onMove={direction => update({ ...item, timeline: moveAt(item.timeline, index, direction) })} /><button type="button" className="danger-action compact" onClick={() => update({ ...item, timeline: removeAt(item.timeline, index) })}>Remove</button></div><div className="field-grid"><Field label="Label" value={entry.label[locale]} onChange={value => updateTimeline(index, { label: { ...entry.label, [locale]: value } })} /><Field label="Title" value={entry.title[locale]} onChange={value => updateTimeline(index, { title: { ...entry.title, [locale]: value } })} /><Field label="Body" value={entry.body[locale]} onChange={value => updateTimeline(index, { body: { ...entry.body, [locale]: value } })} multiline /></div><MediaSlotEditor label="Timeline image" locale={locale} media={entry.media} fallback={`${PUBLIC}/starter-media/movera-hero-field.svg`} onChange={media => updateTimeline(index, { media })} onUpload={file => uploadMedia(file, asset => updateTimeline(index, { media: asset }))} /></article>)}
    {(item.aboutLayout === "leadership" || item.profiles) && <div className="structured-group-heading"><strong>Leadership team</strong><button type="button" className="secondary-action compact" onClick={addProfile}>Add team member</button></div>}
    {item.profiles?.map((profile, index) => <article className="structured-card" key={profile.id}><div className="structured-card-heading"><strong>Leadership profile {String(index + 1).padStart(2, "0")}</strong><span>{profile.id}</span><ReorderControls index={index} length={item.profiles?.length || 0} onMove={direction => update({ ...item, profiles: moveAt(item.profiles, index, direction) })} /><button type="button" className="danger-action compact" onClick={() => update({ ...item, profiles: removeAt(item.profiles, index) })}>Remove</button></div><div className="field-grid"><Field label="Name" value={profile.name[locale]} onChange={value => updateProfile(index, { name: { ...profile.name, [locale]: value } })} /><Field label="Role" value={profile.role[locale]} onChange={value => updateProfile(index, { role: { ...profile.role, [locale]: value } })} /><Field label="Biography / summary" value={profile.summary[locale]} onChange={value => updateProfile(index, { summary: { ...profile.summary, [locale]: value } })} multiline /></div><MediaSlotEditor label="Portrait" locale={locale} media={profile.portrait} fallback={`${PUBLIC}/starter-media/movera-hero-field.svg`} onChange={media => updateProfile(index, { portrait: media })} onUpload={file => uploadMedia(file, asset => updateProfile(index, { portrait: asset }))} /></article>)}
    {(item.aboutLayout === "certificates" || item.credentials) && <div className="structured-group-heading"><strong>Credentials</strong><button type="button" className="secondary-action compact" onClick={addCredential}>Add credential</button></div>}
    {item.credentials?.map((credential, index) => <article className="structured-card" key={credential.id}><div className="structured-card-heading"><strong>Credential {String(index + 1).padStart(2, "0")}</strong><span>{credential.id}</span><ReorderControls index={index} length={item.credentials?.length || 0} onMove={direction => update({ ...item, credentials: moveAt(item.credentials, index, direction) })} /><button type="button" className="danger-action compact" onClick={() => update({ ...item, credentials: removeAt(item.credentials, index) })}>Remove</button></div><div className="field-grid"><Field label="Title" value={credential.title[locale]} onChange={value => updateCredential(index, { title: { ...credential.title, [locale]: value } })} /><Field label="Issuer" value={credential.issuer[locale]} onChange={value => updateCredential(index, { issuer: { ...credential.issuer, [locale]: value } })} /><Field label="Description" value={credential.description[locale]} onChange={value => updateCredential(index, { description: { ...credential.description, [locale]: value } })} multiline /></div><MediaSlotEditor label="Credential image" locale={locale} media={credential.media} fallback={`${PUBLIC}/starter-media/movera-hero-field.svg`} onChange={media => updateCredential(index, { media })} onUpload={file => uploadMedia(file, asset => updateCredential(index, { media: asset }))} /></article>)}
    {!item.sections?.length && !item.timeline?.length && !item.profiles?.length && !item.credentials?.length && <p className="structured-empty">This page uses the standard title, summary, body, and cover fields above.</p>}
  </section>;
}

function EnhancedContentEditor({ setNotice, user }: { setNotice: (value: string) => void; user: User }) {
  const [site, setSite] = useState<SiteData | null>(null);
  const [type, setType] = useState<ContentItem["type"]>("pages");
  const [locale, setLocale] = useState<Locale>("en");
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState<EditableDocument | null>(null);
  const [savedSnapshot, setSavedSnapshot] = useState<EditableDocument | null>(null);
  const [undoStack, setUndoStack] = useState<EditableDocument[]>([]);
  const [redoStack, setRedoStack] = useState<EditableDocument[]>([]);
  const [preview, setPreview] = useState(false);
  const [showHomepage, setShowHomepage] = useState(false);
  const canEdit = user.role !== "Viewer";
  const canPublish = user.role === "Super Admin" || user.role === "Publisher";
  useEffect(() => { api("/api/v1/admin/site").then(response => response.json()).then(payload => setSite(payload.data)).catch(() => setNotice("The content API is unavailable")); }, [setNotice]);
  const items = useMemo(() => (site?.[type] || []).filter(item => `${item.title.en} ${item.title.ar} ${item.title.fr} ${item.title.nl}`.toLowerCase().includes(query.toLowerCase())), [site, type, query]);
  const startEdit = (item: ContentItem) => { const next = type === "pages" && item.id === "ceo-message" && site?.ceoMessage ? copy(site.ceoMessage) : copy(item); setEditing(next); setSavedSnapshot(copy(next)); setUndoStack([]); setRedoStack([]); setPreview(false); };
  const update = (next: EditableDocument) => { if (!editing) return; setUndoStack(stack => [...stack.slice(-19), copy(editing)]); setRedoStack([]); setEditing(next); };
  const updateLocalized = (field: "title" | "slug" | "summary" | "body", value: string) => { if (!editing) return; if (isCEOMessage(editing)) { if (field !== "title") return; update({ ...editing, title: { ...editing.title, [locale]: value } }); return; } update({ ...editing, [field]: { ...editing[field], [locale]: value } }); };
  const undo = () => { if (!editing || undoStack.length === 0) return; const previous = undoStack[undoStack.length - 1]; setUndoStack(stack => stack.slice(0, -1)); setRedoStack(stack => [...stack, copy(editing)]); setEditing(previous); };
  const redo = () => { if (!editing || redoStack.length === 0) return; const next = redoStack[redoStack.length - 1]; setRedoStack(stack => stack.slice(0, -1)); setUndoStack(stack => [...stack, copy(editing)]); setEditing(next); };
  const historyRef = useRef({ undo, redo });
  historyRef.current = { undo, redo };
  useEffect(() => {
    const handleHistoryShortcut = (event: KeyboardEvent) => {
      if (!editing || !(event.ctrlKey || event.metaKey)) return;
      const key = event.key.toLowerCase();
      if (key === "z") { event.preventDefault(); event.shiftKey ? historyRef.current.redo() : historyRef.current.undo(); }
      if (key === "y") { event.preventDefault(); historyRef.current.redo(); }
    };
    window.addEventListener("keydown", handleHistoryShortcut);
    return () => window.removeEventListener("keydown", handleHistoryShortcut);
  }, [editing]);
  const reset = () => { if (savedSnapshot) { setEditing(copy(savedSnapshot)); setUndoStack([]); setRedoStack([]); setNotice("Unsaved changes reset to the last saved version"); } };
  const uploadMedia = async (file: File, apply: (asset: MediaAsset) => void) => { const form = new FormData(); form.append("file", file); setNotice("Uploading media…"); const response = await api("/api/v1/media", { method: "POST", body: form }); const payload = await response.json(); if (!response.ok) { setNotice(payload.error?.message || "Media upload failed"); return; } apply(uploadedMedia(payload.data as MediaAsset, { id: payload.data.id, url: payload.data.url, alt: emptyLocale(), focalX: 50, focalY: 50, zoom: 1 })); setNotice("Media uploaded · save the draft to apply it"); };
  const save = async () => {
    if (!editing || !canEdit) return;
    setNotice("Saving draft…");
    const ceo = isCEOMessage(editing);
    const item = ceo ? undefined : editing as ContentItem;
    const path = ceo ? "/api/v1/admin/ceo-message" : item?.id ? `/api/v1/content/${type}/${item.id}` : `/api/v1/content/${type}`;
    const method = ceo || item?.id ? "PUT" : "POST";
    const response = await api(path, { method, body: JSON.stringify({ ...editing, status: "draft" }) });
    const payload = await response.json();
    if (!response.ok) { setNotice("Draft could not be saved"); return; }
    const next = payload.data as EditableDocument;
    setSite(current => current ? (ceo ? { ...current, ceoMessage: next as CEOMessageContent } : { ...current, [type]: item?.id ? current[type].map(row => row.id === (next as ContentItem).id ? next as ContentItem : row) : [next as ContentItem, ...current[type]] }) : current);
    setEditing(copy(next)); setSavedSnapshot(copy(next)); setUndoStack([]); setRedoStack([]); setNotice("Draft saved · publish it to update the public page");
  };
  const lifecycle = async (status: "published" | "archived" | "draft") => {
    if (!editing || !canPublish) return;
    const ceo = isCEOMessage(editing);
    setNotice(status === "published" ? "Publishing…" : status === "archived" ? "Archiving…" : "Restoring…");
    const response = await api(ceo ? "/api/v1/admin/ceo-message/status" : `/api/v1/admin/content/${type}/${editing.id}/status`, { method: "PATCH", body: JSON.stringify({ status }) });
    const payload = await response.json();
    if (!response.ok) { setNotice("Action not permitted"); return; }
    const next = payload.data as EditableDocument;
    setEditing(copy(next)); setSavedSnapshot(copy(next)); setSite(current => current ? (ceo ? { ...current, ceoMessage: next as CEOMessageContent } : { ...current, [type]: current[type].map(item => item.id === (next as ContentItem).id ? next as ContentItem : item) }) : current); setNotice(status === "published" ? "Published · public page updated" : status === "archived" ? "Archived from the public site" : "Restored as a draft");
  };
  const remove = async () => { if (!editing || isCEOMessage(editing) || user.role !== "Super Admin") return; if (!window.confirm("Move this content to Trash? You can restore it later from the Trash workspace.")) return; const response = await api(`/api/v1/content/${type}/${editing.id}`, { method: "DELETE" }); if (!response.ok) { setNotice("Content could not be moved to Trash"); return; } setSite(current => current ? { ...current, [type]: current[type].filter(item => item.id !== editing.id) } : current); setEditing(null); setSavedSnapshot(null); setNotice("Content moved to Trash"); };
  const moveItem = async (itemId: string, direction: "up" | "down") => {
    if (!site || !canEdit) return;
    setNotice("Saving order…");
    const response = await api(`/api/v1/content/${type}/${itemId}/order`, { method: "PATCH", body: JSON.stringify({ direction }) });
    const payload = await response.json();
    if (!response.ok) { setNotice("Order could not be saved"); return; }
    setSite(current => current ? { ...current, [type]: payload.data.items } : current);
    setNotice("Order saved");
  };
  if (!site) return <div className="workspace-loading">Loading content workspace…</div>;
  if (showHomepage) return <HomepageEditor site={site} setSite={setSite} locale={locale} setLocale={setLocale} canEdit={canEdit} setNotice={setNotice} onBack={() => setShowHomepage(false)} />;
  const ceo = editing && isCEOMessage(editing) ? editing : null;
  const page = editing && !isCEOMessage(editing) ? editing : null;
  const editingKey = editing ? (isCEOMessage(editing) ? editing.slug : editing.id) : "";
  const previewSlug = ceo ? ceo.slug : page ? page.slug[locale] || page.slug.en : "";
  const rowStatus = (item: ContentItem) => item.id === "ceo-message" && site.ceoMessage ? site.ceoMessage.status || "published" : item.status || "published";
  const canMoveItem = (itemId: string, direction: "up" | "down") => { const index = site[type].findIndex(item => item.id === itemId); return direction === "up" ? index > 0 : index >= 0 && index < site[type].length - 1; };

  const rowImage = (item: ContentItem) => item.id === "ceo-message" && site.ceoMessage ? publicMediaUrl(site.ceoMessage.portrait.url) : item.id === "leadership" || item.id === "clients-certificates" ? `${PUBLIC}/about-generic.svg` : previewUrl(item);
  const updateCEOMessage = (index: number, value: string) => {
    if (!ceo) return;
    update({ ...ceo, message: ceo.message.map((paragraph, paragraphIndex) => paragraphIndex === index ? { ...paragraph, [locale]: value } : paragraph) });
  };
  const uploadCEOPortrait = async (file: File) => {
    if (!ceo) return;
    await uploadMedia(file, asset => update({ ...ceo, portrait: asset }));
  };

  if (!site) return <div className="workspace-loading">Loading content workspace…</div>;
  return <div className="workspace">
    <div className="editor-toolbar">
      <div className="select-stack">
        <AdminSelect value={type} options={contentSectionOptions} ariaLabel="Content collection" onChange={value => { setType(value); setEditing(null); }} />
        <div className="search-control"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder={`Search ${labels[type].toLowerCase()}`} /></div>
      </div>
       <div className="toolbar-meta"><span className="locked-pill">Design system locked</span><button className="secondary-action compact" type="button" onClick={() => { setEditing(null); setShowHomepage(true); }}>Edit home page</button><a href={publicUrl(type, "en")} target="_blank" rel="noreferrer">View collection ↗</a></div>
     </div>
     {type === "news" && <RotatingNewsSelector site={site} setSite={setSite} locale={locale} canEdit={canEdit} setNotice={setNotice} />}
     <div className="editor-layout">
      <section className="content-index">
        <div className="index-head"><div><p className="eyebrow">Structured content</p><h2>{labels[type]}</h2></div>{canEdit && <button className="secondary-action" onClick={() => { if (type === "pages") setNotice("Select an existing About page to preserve its public structure"); else startEdit(emptyItem(type)); }}>New {type === "news" ? "item" : labels[type].replace(/s$/, "")}</button>}</div>
        <p className="section-copy">Select a page to edit the fields and media currently rendered on the public site.</p>
        <div className="content-list">{items.map(item => <div className={`content-entry ${editingKey === item.id ? "selected" : ""}`} key={item.id}>
          <button type="button" className="content-entry-main" onClick={() => startEdit(item)}>
            <span className="entry-thumb"><img {...(item.id === "ceo-message" && site.ceoMessage ? optimizedMediaProps(site.ceoMessage.portrait, rowImage(item)) : optimizedMediaProps(item.cover, rowImage(item)))} alt="" loading="lazy" /></span>
            <span className="entry-copy"><strong>{item.id === "ceo-message" && site.ceoMessage ? site.ceoMessage.title.en : item.title.en || "Untitled content"}</strong><small>{item.id === "ceo-message" && site.ceoMessage ? site.ceoMessage.slug : item.slug.en || "No English slug"}</small></span>
            <span className={`status-tag ${rowStatus(item)}`}>{rowStatus(item)}</span><span className="entry-arrow">→</span>
          </button>
          {canEdit && <span className="entry-order-actions"><button type="button" className="entry-order-action" onClick={() => void moveItem(item.id, "up")} disabled={!canMoveItem(item.id, "up")} aria-label={`Move ${item.title.en || "content"} up`}>↑</button><button type="button" className="entry-order-action" onClick={() => void moveItem(item.id, "down")} disabled={!canMoveItem(item.id, "down")} aria-label={`Move ${item.title.en || "content"} down`}>↓</button></span>}
        </div>)}{items.length === 0 && <div className="empty-state">No matching content.</div>}</div>
      </section>
      {editing ? <section className="editor-pane">
        <div className="pane-head"><div><p className="eyebrow">Edit mode · {labels[type]}</p><h2>{ceo ? ceo.title.en : page?.title.en || "Untitled content"}</h2></div><div className="pane-actions"><button className="icon-action" onClick={undo} disabled={!undoStack.length} title="Undo" aria-label="Undo last edit">↶ Undo</button><button className="icon-action" onClick={redo} disabled={!redoStack.length} title="Redo" aria-label="Redo last edit">↷ Redo</button><button className="text-action" onClick={reset}>Reset to default</button><button className="text-action" onClick={() => setPreview(value => !value)}>{preview ? "Edit fields" : "Preview page"}</button></div></div>
        {preview ? <div className="preview-frame"><iframe title="Public page preview" src={publicUrl("pages", locale, previewSlug)} /><div className="preview-lock">Preview uses the public renderer · layout remains locked</div></div> : <>
          <div className="editor-locales"><LocaleTabs locale={locale} setLocale={setLocale} /><span>{locale === "ar" ? "RTL content editing" : "Native content locale"}</span></div>
          {ceo ? <div className="editable-surface" dir={locale === "ar" ? "rtl" : "ltr"}>
            <div className="field-grid"><Field label="Title" value={ceo.title[locale]} onChange={value => update({ ...ceo, title: { ...ceo.title, [locale]: value } })} /><Field label="Slug" value={ceo.slug} onChange={value => update({ ...ceo, slug: value })} hint="Used by the public About route" /><Field label="Name" value={ceo.name[locale]} onChange={value => update({ ...ceo, name: { ...ceo.name, [locale]: value } })} /><Field label="Position" value={ceo.position[locale]} onChange={value => update({ ...ceo, position: { ...ceo.position, [locale]: value } })} /></div>
            <div className="structured-editor"><div className="structured-editor-heading"><div><p className="eyebrow">Full message</p><h3>Visible paragraphs and pull quote</h3></div><span>Edit every paragraph shown on the public CEO page.</span></div>{ceo.message.map((paragraph, index) => <article className="structured-card" key={index}><div className="structured-card-heading"><strong>Paragraph {String(index + 1).padStart(2, "0")}</strong><span>CEO message</span></div><Field label="Message" value={paragraph[locale]} onChange={value => updateCEOMessage(index, value)} multiline /></article>)}<article className="structured-card"><div className="structured-card-heading"><strong>Pull quote</strong><span>Optional</span></div><Field label="Quote" value={ceo.pullQuote?.[locale] || ""} onChange={value => update({ ...ceo, pullQuote: { ...(ceo.pullQuote || emptyLocale()), [locale]: value } })} multiline /></article></div>
            <MediaSlotEditor label="CEO portrait" locale={locale} media={ceo.portrait} fallback={`${PUBLIC}/starter-media/portrait.svg`} onChange={media => media && update({ ...ceo, portrait: media })} onUpload={uploadCEOPortrait} />
          </div> : page ? <div className="editable-surface" dir={locale === "ar" ? "rtl" : "ltr"}>
            <div className="field-grid"><Field label="Title" value={page.title[locale]} onChange={value => update({ ...page, title: { ...page.title, [locale]: value } })} /><Field label="Slug" value={page.slug[locale]} onChange={value => update({ ...page, slug: { ...page.slug, [locale]: value } })} hint="Used in this locale only" /><Field label="Summary" value={page.summary[locale]} onChange={value => update({ ...page, summary: { ...page.summary, [locale]: value } })} multiline /><Field label="Body" value={page.body[locale]} onChange={value => update({ ...page, body: { ...page.body, [locale]: value } })} multiline /><Field label="Sector / category" value={page.category || page.sector || ""} onChange={value => update({ ...page, category: value, sector: value })} /><Field label="Tags" value={(page.tags || []).join(", ")} onChange={value => update({ ...page, tags: value.split(",").map(tag => tag.trim()).filter(Boolean) })} /></div>
            <MediaSlotEditor label="Cover image" locale={locale} media={page.cover} fallback={`${PUBLIC}/starter-media/movera-hero-field.svg`} onChange={media => update({ ...page, cover: media })} onUpload={file => uploadMedia(file, asset => update({ ...page, cover: asset }))} />
            <StructuredContentFields item={page} locale={locale} update={next => update(next)} uploadMedia={uploadMedia} />
          </div> : null}
          <div className="save-rail"><span>Changes are scoped to {localeLabels[locale]} unless the field is shared.</span><div><button className="secondary-action" onClick={() => setEditing(null)}>Close</button><button className="primary-action compact" onClick={save} disabled={!canEdit}>Save draft <span>→</span></button>{canPublish && page?.id && type !== "pages" && <>{page.status === "archived" ? <button className="secondary-action" onClick={() => void lifecycle("draft")}>Restore</button> : <button className="publish-action" onClick={() => void lifecycle(page.status === "published" || !page.status ? "archived" : "published")}>{page.status === "published" || !page.status ? "Archive" : "Publish"}</button>}{user.role === "Super Admin" && <button className="danger-action" onClick={() => void remove()}>Delete</button>}</>}</div></div>
        </>}
      </section> : <div className="empty-editor"><div className="empty-orbit">✦</div><h2>Choose a page to edit</h2><p>The public renderer stays visible in Preview, while approved text and media fields remain editable here.</p></div>}
    </div>
  </div>;
}

const homepageBandLabels: Record<HomepageBandId, string> = {
  locations: "Locations and statistics",
  news: "Latest news",
  products: "Featured products",
  projects: "Featured projects",
  careers: "Latest careers",
  customers: "Customer names",
};

function homepageItemsForBand(site: SiteData, id: HomepageBandId) {
  if (id === "news") return site.news;
  if (id === "products") return site.products;
  if (id === "projects" || id === "customers") return site.projects;
  if (id === "careers") return site.jobs;
  return [];
}

function homepageItemLabel(item: ContentItem, id: HomepageBandId, locale: Locale) {
  if (id === "customers") return item.client?.trim() || item.title[locale] || item.title.en;
  return item.title[locale] || item.title.en || item.id;
}

function RotatingNewsSelector({ site, setSite, locale, canEdit, setNotice }: { site: SiteData; setSite: Dispatch<SetStateAction<SiteData | null>>; locale: Locale; canEdit: boolean; setNotice: (value: string) => void }) {
  const availableNews = site.news;
  const fallbackIds = availableNews.filter(item => item.status !== "archived" && item.status !== "draft").slice(0, 5).map(item => item.id);
  const [selectedIds, setSelectedIds] = useState<string[]>(() => [...new Set(site.homepage.latestNews?.length ? site.homepage.latestNews : fallbackIds)]);
  const newsById = useMemo(() => new Map(availableNews.map(item => [item.id, item])), [availableNews]);
  const selectedItems = selectedIds.map(id => newsById.get(id)).filter((item): item is ContentItem => Boolean(item));
  const titleFor = (item: ContentItem) => item.title[locale] || item.title.en || item.id;
  const toggle = (itemId: string) => {
    if (selectedIds.includes(itemId)) {
      if (selectedIds.length === 1) { setNotice("Keep at least one News item in the rotating bar"); return; }
      setSelectedIds(current => current.filter(id => id !== itemId));
      return;
    }
    setSelectedIds(current => [...current, itemId]);
  };
  const save = async () => {
    if (!canEdit || !selectedIds.length) return;
    setNotice("Saving rotating News bar…");
    const response = await api("/api/v1/homepage", { method: "PUT", body: JSON.stringify({ ...site.homepage, latestNews: selectedIds }) });
    const payload = await response.json();
    if (!response.ok) { setNotice(payload.error?.message || "Rotating News bar could not be saved"); return; }
    const next = payload.data as HomepageContent;
    setSelectedIds([...next.latestNews]);
    setSite(current => current ? { ...current, homepage: next } : current);
    setNotice("Rotating News bar saved · public ticker updated");
  };

  return <section className="rotating-news-editor" aria-label="Rotating News bar settings">
    <div className="structured-editor-heading rotating-news-editor-heading"><div><p className="eyebrow">News collection</p><h3>Choose news for the top rotating bar</h3></div><span>Select the headlines used by the slim News rail in the public header. This selection is shared across all four locales; the active locale changes the displayed title.</span></div>
    <div className="rotating-news-layout">
      <div className="rotating-news-available"><div className="structured-group-heading"><strong>Available News</strong><span>{selectedIds.length} selected</span></div><div className="rotating-news-options">{availableNews.map(item => <label className="rotating-news-option" key={item.id}><input type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => toggle(item.id)} disabled={!canEdit} aria-label={`Show ${titleFor(item)} in rotating News bar`} /><span><strong>{titleFor(item)}</strong><small>{item.id} · {item.status || "published"}</small></span></label>)}{!availableNews.length && <p className="structured-empty">No News items are available. Create and publish a News item first.</p>}</div></div>
      <div className="rotating-news-selected"><div className="structured-group-heading"><strong>Selected order</strong><span>Headlines rotate in this order</span></div><div className="rotating-news-order">{selectedItems.map((item, index) => <article className="rotating-news-order-row" key={item.id}><span className="rotating-news-order-number">{String(index + 1).padStart(2, "0")}</span><span className="rotating-news-order-copy"><strong>{titleFor(item)}</strong><small>{item.status || "published"}</small></span><ReorderControls index={index} length={selectedItems.length} onMove={direction => setSelectedIds(current => moveAt(current, index, direction) || current)} /></article>)}{!selectedItems.length && <p className="structured-empty">Select at least one News item to populate the ticker.</p>}</div></div>
    </div>
    <div className="save-rail rotating-news-save"><span>Only published headlines render publicly; drafts remain selectable for a future publish.</span><button type="button" className="primary-action compact" onClick={() => void save()} disabled={!canEdit || !selectedIds.length}>Save rotating bar <span>→</span></button></div>
  </section>;
}

function HomepageEditor({ site, setSite, locale, setLocale, canEdit, setNotice, onBack }: { site: SiteData; setSite: Dispatch<SetStateAction<SiteData | null>>; locale: Locale; setLocale: (locale: Locale) => void; canEdit: boolean; setNotice: (value: string) => void; onBack: () => void }) {
  const [draft, setDraft] = useState<HomepageContent>(() => copy(site.homepage));
  const [savedSnapshot, setSavedSnapshot] = useState<HomepageContent>(() => copy(site.homepage));
  const [undoStack, setUndoStack] = useState<HomepageContent[]>([]);
  const [redoStack, setRedoStack] = useState<HomepageContent[]>([]);
  const [saving, setSaving] = useState(false);
  const [showAllItems, setShowAllItems] = useState<Record<HomepageBandId, boolean>>({ locations: true, news: false, products: false, projects: false, careers: false, customers: false });

  const update = (next: HomepageContent) => { setUndoStack(stack => [...stack.slice(-19), copy(draft)]); setRedoStack([]); setDraft(next); };
  const updateHeroText = (field: "eyebrow" | "title" | "description" | "primaryLabel" | "secondaryLabel", value: string) => update({ ...draft, hero: { ...draft.hero, [field]: { ...draft.hero[field], [locale]: value } } });
  const updateIntro = (field: "title" | "body", value: string) => update({ ...draft, intro: { ...draft.intro, [field]: { ...draft.intro[field], [locale]: value } } });
  const updateBand = (index: number, patch: Partial<HomepageBand>) => update({ ...draft, bands: draft.bands.map((band, bandIndex) => bandIndex === index ? { ...band, ...patch } : band) });
  const updateBandText = (index: number, field: "eyebrow" | "title" | "body" | "viewLabel", value: string) => { const band = draft.bands[index]; updateBand(index, { [field]: { ...band[field], [locale]: value } }); };
  const toggleItem = (bandIndex: number, itemId: string) => { const band = draft.bands[bandIndex]; const itemIds = band.itemIds.includes(itemId) ? band.itemIds.filter(id => id !== itemId) : [...band.itemIds, itemId]; updateBand(bandIndex, { itemIds }); };
  const undo = () => { if (!undoStack.length) return; const previous = undoStack[undoStack.length - 1]; setUndoStack(stack => stack.slice(0, -1)); setRedoStack(stack => [...stack, copy(draft)]); setDraft(previous); };
  const redo = () => { if (!redoStack.length) return; const next = redoStack[redoStack.length - 1]; setRedoStack(stack => stack.slice(0, -1)); setUndoStack(stack => [...stack, copy(draft)]); setDraft(next); };
  const reset = () => { setDraft(copy(savedSnapshot)); setUndoStack([]); setRedoStack([]); setNotice("Homepage changes reset to the last saved version"); };
  const uploadMedia = async (file: File, apply: (asset: MediaAsset) => void) => { const form = new FormData(); form.append("file", file); setNotice("Uploading media…"); const response = await api("/api/v1/media", { method: "POST", body: form }); const payload = await response.json(); if (!response.ok) { setNotice(payload.error?.message || "Media upload failed"); return; } apply(uploadedMedia(payload.data as MediaAsset, { id: payload.data.id, url: payload.data.url, alt: emptyLocale(), caption: emptyLocale(), focalX: 50, focalY: 50, zoom: 1 })); setNotice("Media uploaded · save the homepage to apply it"); };
  const save = async () => { if (!canEdit || saving) return; setSaving(true); setNotice("Saving homepage…"); const response = await api("/api/v1/homepage", { method: "PUT", body: JSON.stringify(draft) }); const payload = await response.json(); if (!response.ok) { setNotice(payload.error?.message || "Homepage could not be saved"); setSaving(false); return; } const next = payload.data as HomepageContent; setDraft(copy(next)); setSavedSnapshot(copy(next)); setSite(current => current ? { ...current, homepage: next } : current); setUndoStack([]); setRedoStack([]); setNotice("Homepage saved · public bars updated"); setSaving(false); };
  const statUpdate = (index: number, patch: Partial<HomepageContent["stats"][number]>) => update({ ...draft, stats: draft.stats.map((stat, statIndex) => statIndex === index ? { ...stat, ...patch } : stat) });
  const addStat = () => update({ ...draft, stats: [...draft.stats, { value: "", label: emptyLocale() }] });

  return <div className="workspace homepage-editor-workspace"><div className="editor-toolbar"><div><p className="eyebrow">Homepage composition</p><h2>Edit home page</h2></div><div className="toolbar-meta"><button className="secondary-action compact" type="button" onClick={onBack}>Back to collections</button><button className="icon-action" type="button" onClick={undo} disabled={!undoStack.length} aria-label="Undo homepage edit">↶ Undo</button><button className="icon-action" type="button" onClick={redo} disabled={!redoStack.length} aria-label="Redo homepage edit">↷ Redo</button></div></div><div className="editor-locales homepage-editor-locales"><LocaleTabs locale={locale} setLocale={setLocale} /><span>Copy fields are edited in the selected native locale. Composition and item selection are shared.</span></div><div className="homepage-editor-body" dir={locale === "ar" ? "rtl" : "ltr"}>
    <section className="structured-editor homepage-editor-section"><div className="structured-editor-heading"><div><p className="eyebrow">First view</p><h3>Hero and triangle introduction</h3></div><span>Change approved copy and the hero media without changing the layout system.</span></div><div className="field-grid"><Field label="Hero eyebrow" value={draft.hero.eyebrow[locale]} onChange={value => updateHeroText("eyebrow", value)} /><Field label="Hero title" value={draft.hero.title[locale]} onChange={value => updateHeroText("title", value)} /><Field label="Hero description" value={draft.hero.description[locale]} onChange={value => updateHeroText("description", value)} multiline /><Field label="Primary button label" value={draft.hero.primaryLabel[locale]} onChange={value => updateHeroText("primaryLabel", value)} /><Field label="Primary button URL" value={draft.hero.primaryHref} onChange={value => update({ ...draft, hero: { ...draft.hero, primaryHref: value } })} /><Field label="Secondary button label" value={draft.hero.secondaryLabel[locale]} onChange={value => updateHeroText("secondaryLabel", value)} /><Field label="Secondary button URL" value={draft.hero.secondaryHref} onChange={value => update({ ...draft, hero: { ...draft.hero, secondaryHref: value } })} /></div><MediaSlotEditor label="Hero background" locale={locale} media={draft.hero.background} fallback={`${PUBLIC}/starter-media/movera-hero-field.svg`} onChange={media => media && update({ ...draft, hero: { ...draft.hero, background: media } })} onUpload={file => uploadMedia(file, asset => update({ ...draft, hero: { ...draft.hero, background: asset } }))} /></section>
    <section className="structured-editor homepage-editor-section"><div className="structured-editor-heading"><div><p className="eyebrow">Homepage copy</p><h3>Intro and statistics</h3></div><span>Statistics are content values; their visual treatment remains locked.</span></div><div className="field-grid"><Field label="Intro title" value={draft.intro.title[locale]} onChange={value => updateIntro("title", value)} /><Field label="Intro body" value={draft.intro.body[locale]} onChange={value => updateIntro("body", value)} multiline /></div><div className="structured-group-heading"><strong>Statistics</strong><button type="button" className="secondary-action compact" onClick={addStat}>Add statistic</button></div>{draft.stats.map((stat, index) => <article className="structured-card homepage-stat-editor" key={index}><div className="structured-card-heading"><strong>Statistic {String(index + 1).padStart(2, "0")}</strong><button type="button" className="danger-action compact" onClick={() => update({ ...draft, stats: draft.stats.filter((_, statIndex) => statIndex !== index) })}>Remove</button></div><div className="field-grid"><Field label="Value" value={stat.value} onChange={value => statUpdate(index, { value })} /><Field label={`Label · ${localeLabels[locale]}`} value={stat.label[locale]} onChange={value => statUpdate(index, { label: { ...stat.label, [locale]: value } })} /></div></article>)}</section>
    <section className="structured-editor homepage-editor-section"><div className="structured-editor-heading"><div><p className="eyebrow">Content bars</p><h3>Choose, edit, and reorder homepage bars</h3></div><span>Hide a bar, change its localized copy, select its live items, then move it up or down.</span></div>{draft.bands.map((band, index) => { const items = homepageItemsForBand(site, band.id); const visibleItems = showAllItems[band.id] ? items : items.slice(0, 12); return <article className="structured-card homepage-band-editor" key={`${band.id}-${index}`}><div className="structured-card-heading homepage-band-editor-heading"><div><strong>{String(index + 1).padStart(2, "0")} · {homepageBandLabels[band.id]}</strong><span>{band.id}</span></div><ReorderControls index={index} length={draft.bands.length} onMove={direction => update({ ...draft, bands: moveAt(draft.bands, index, direction) || draft.bands })} /></div><label className="setting-check homepage-band-visible"><input type="checkbox" checked={band.visible} onChange={event => updateBand(index, { visible: event.target.checked })} />Show this bar on the public homepage</label><div className="field-grid"><Field label="Eyebrow" value={band.eyebrow[locale]} onChange={value => updateBandText(index, "eyebrow", value)} /><Field label="Title" value={band.title[locale]} onChange={value => updateBandText(index, "title", value)} /><Field label="Description" value={band.body[locale]} onChange={value => updateBandText(index, "body", value)} multiline /><Field label="Link label" value={band.viewLabel[locale]} onChange={value => updateBandText(index, "viewLabel", value)} /></div>{band.id === "locations" ? <p className="structured-empty">This bar uses the managed branch locations and live statistics. Edit its copy here; branches and directions are managed in Regions.</p> : <div className="homepage-band-selection"><div className="structured-group-heading"><strong>Items shown in this bar</strong><span>{band.itemIds.length} selected · order follows your selection</span></div><div className="homepage-band-items">{visibleItems.map(item => <label className="homepage-band-item" key={`${band.id}-${item.id}`}><input type="checkbox" checked={band.itemIds.includes(item.id)} onChange={() => toggleItem(index, item.id)} /><span><strong>{homepageItemLabel(item, band.id, locale)}</strong><small>{item.id} · {item.status || "published"}</small></span></label>)}</div>{items.length > 12 && <button type="button" className="text-action" onClick={() => setShowAllItems(current => ({ ...current, [band.id]: !current[band.id] }))}>{showAllItems[band.id] ? "Show fewer items" : `Show all ${items.length} items`}</button>}<p className="field-hint">Only published items can appear publicly. Draft and archived items remain selectable so the composition is ready when they are published.</p></div>}</article>; })}</section>
    <div className="save-rail homepage-save-rail"><span>Changes apply to the public homepage after saving. Undo and redo are available until you save.</span><div><button className="secondary-action" type="button" onClick={reset}>Reset</button><button className="primary-action compact" type="button" onClick={() => void save()} disabled={!canEdit || saving}>{saving ? "Saving…" : "Save homepage"} <span>→</span></button></div></div>
  </div></div>;
}

function TrashWorkspace({ setNotice }: { setNotice: (value: string) => void }) {
  const [items, setItems] = useState<TrashItem[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [query, setQuery] = useState("");
  const load = async () => { const response = await api("/api/v1/admin/trash"); if (response.ok) setItems((await response.json()).data || []); else setNotice("Trash could not be loaded"); };
  useEffect(() => { void load(); }, []);
  const visible = items.filter(entry => `${entry.item.title.en} ${entry.item.slug.en} ${entry.type} ${entry.deletedBy || ""}`.toLowerCase().includes(query.toLowerCase()));
  const toggle = (trashId: string) => setSelected(current => { const next = new Set(current); if (next.has(trashId)) next.delete(trashId); else next.add(trashId); return next; });
  const restore = async (entry: TrashItem) => { const response = await api(`/api/v1/admin/trash/${entry.type}/${encodeURIComponent(entry.item.id)}/restore`, { method: "POST" }); if (!response.ok) { setNotice("Item could not be restored"); return; } setItems(current => current.filter(item => item.trashId !== entry.trashId)); setSelected(current => { const next = new Set(current); next.delete(entry.trashId); return next; }); setNotice("Content restored to its original position"); };
  const permanentlyDelete = async (entry: TrashItem) => { if (!window.confirm(`Permanently delete “${entry.item.title.en || entry.item.id}”? This cannot be undone.`)) return; const response = await api(`/api/v1/admin/trash/${entry.type}/${encodeURIComponent(entry.item.id)}`, { method: "DELETE" }); if (!response.ok) { setNotice("Item could not be permanently deleted"); return; } setItems(current => current.filter(item => item.trashId !== entry.trashId)); setSelected(current => { const next = new Set(current); next.delete(entry.trashId); return next; }); setNotice("Item permanently deleted"); };
  const deleteSelected = async () => { if (!selected.size || !window.confirm(`Permanently delete ${selected.size} selected item${selected.size === 1 ? "" : "s"}? This cannot be undone.`)) return; const response = await api("/api/v1/admin/trash", { method: "DELETE", body: JSON.stringify({ ids: [...selected] }) }); if (!response.ok) { setNotice("Selected items could not be deleted"); return; } setSelected(new Set()); await load(); setNotice("Selected items permanently deleted"); };
  const emptyTrash = async () => { if (!items.length || !window.confirm(`Empty Trash and permanently delete all ${items.length} item${items.length === 1 ? "" : "s"}? This cannot be undone.`)) return; const response = await api("/api/v1/admin/trash", { method: "DELETE", body: JSON.stringify({}) }); if (!response.ok) { setNotice("Trash could not be emptied"); return; } setSelected(new Set()); setItems([]); setNotice("Trash emptied"); };
  return <div className="workspace trash-workspace"><div className="workspace-intro"><div><p className="eyebrow">Recovery workspace</p><h2>Trash</h2><p>Deleted top-level content stays here until it is restored or permanently removed. Full About pages remain protected from deletion.</p></div><div className="trash-actions"><button className="danger-action" onClick={() => void deleteSelected()} disabled={!selected.size}>Delete selected</button><button className="secondary-action" onClick={() => void emptyTrash()} disabled={!items.length}>Empty Trash</button></div></div><div className="metrics-row"><Metric value={String(items.length)} label="Items in Trash" /><Metric value={String(selected.size)} label="Selected" /><Metric value="∞" label="Restore available" /></div><div className="list-toolbar"><div className="search-control"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search deleted content" /></div><span className="muted-label">Super Admin only · permanent deletion is final</span></div><div className="trash-list">{visible.map(entry => <article className="trash-row" key={entry.trashId}><label className="trash-select"><input type="checkbox" checked={selected.has(entry.trashId)} onChange={() => toggle(entry.trashId)} aria-label={`Select ${entry.item.title.en || entry.item.id}`} /></label><span className="entry-thumb"><img {...optimizedMediaProps(entry.item.cover, `${PUBLIC}/starter-media/movera-hero-field.svg`)} alt="" loading="lazy" /></span><div className="trash-copy"><strong>{entry.item.title.en || "Untitled content"}</strong><small>{labels[entry.type]} · {entry.item.slug.en || entry.item.id}</small><small>Deleted {new Date(entry.deletedAt).toLocaleString()} {entry.deletedBy ? `by ${entry.deletedBy}` : ""}</small></div><span className={`status-tag ${entry.item.status || "published"}`}>{entry.item.status || "published"}</span><div className="trash-row-actions"><button className="secondary-action compact" onClick={() => void restore(entry)}>Restore</button><button className="danger-action compact" onClick={() => void permanentlyDelete(entry)}>Delete forever</button></div></article>)}{visible.length === 0 && <div className="empty-state">{items.length ? "No matching deleted content." : "Trash is empty. Deleted content will appear here."}</div>}</div></div>;
}

function UserManagement({ setNotice, user }: { setNotice: (value: string) => void; user: User }) {
  const [users, setUsers] = useState<User[]>([]);
  const [audits, setAudits] = useState<any[]>([]);
  const [query, setQuery] = useState("");
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState({ name: "", email: "", password: "", role: "Content Editor" as Role });
  const canManage = user.role === "Super Admin" || user.role === "User Manager";
  const load = async () => { const response = await api(`/api/v1/admin/users?q=${encodeURIComponent(query)}`); if (response.ok) setUsers((await response.json()).data); };
  useEffect(() => { void load(); api("/api/v1/admin/audit").then(response => response.ok ? response.json() : null).then(payload => payload && setAudits(payload.data || [])); }, [query]);
  const create = async (event: React.FormEvent) => { event.preventDefault(); const response = await api("/api/v1/admin/users", { method: "POST", body: JSON.stringify({ ...form, forcePasswordReset: true }) }); if (!response.ok) { setNotice("User could not be created"); return; } setShowCreate(false); setForm({ name: "", email: "", password: "", role: "Content Editor" }); setNotice("User created with forced password reset"); void load(); };
  const toggle = async (row: User) => { const response = await api(`/api/v1/admin/users/${row.id}`, { method: "PATCH", body: JSON.stringify({ active: !row.active }) }); if (response.ok) { setNotice(row.active ? "User deactivated" : "User activated"); void load(); } else setNotice("This user cannot be changed"); };
  const forceReset = async (row: User) => { const response = await api(`/api/v1/admin/users/${row.id}`, { method: "PATCH", body: JSON.stringify({ forcePasswordReset: true }) }); setNotice(response.ok ? "Password reset required at next sign-in" : "Password reset could not be applied"); if (response.ok) void load(); };
  return <div className="workspace"><div className="workspace-intro"><div><p className="eyebrow">Access governance</p><h2>People with a reason to be here.</h2><p>Every role is enforced by the API. Keep access explicit, reviewable, and easy to revoke.</p></div>{canManage && <button className="primary-action compact" onClick={() => setShowCreate(true)}>Add local user <span>+</span></button>}</div><div className="metrics-row"><Metric value={String(users.length)} label="Local users" /><Metric value={String(users.filter(row => row.active).length)} label="Active access" /><Metric value={String(users.filter(row => row.forcePasswordReset).length)} label="Reset required" /></div><div className="list-toolbar"><div className="search-control"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search users, roles, or email" /></div><span className="muted-label">Backend authorization enabled</span></div><div className="user-list"><div className="user-list-head"><span>User</span><span>Role</span><span>Last sign-in</span><span>Status</span><span>Actions</span></div>{users.map(row => <div className="user-row" key={row.id}><div className="user-identity"><span className="avatar">{row.name.slice(0, 1)}</span><span><strong>{row.name}</strong><small>{row.email}</small></span></div><span className="role-pill">{row.role}</span><span className="muted-label">{row.lastLoginAt ? new Date(row.lastLoginAt).toLocaleDateString() : "Never"}</span><button className={`status-toggle ${row.active ? "on" : ""}`} onClick={() => canManage && void toggle(row)} disabled={!canManage}><i />{row.active ? "Active" : "Inactive"}</button><button className="text-action" onClick={() => canManage && void forceReset(row)} disabled={!canManage || row.forcePasswordReset}>{row.forcePasswordReset ? "Reset required" : "Force reset"}</button></div>)}</div><section className="audit-panel"><div className="panel-title"><span className="panel-icon">⌁</span><div><h3>Recent audit history</h3><p>Administrative actions are retained for review.</p></div></div>{audits.slice(0, 6).map(event => <div className="audit-row" key={event.id}><span>{event.action}</span><strong>{event.entity}</strong><small>{event.user?.name || "Admin"} · {new Date(event.createdAt).toLocaleString()}</small></div>)}</section>{showCreate && <div className="modal-backdrop" onClick={() => setShowCreate(false)}><form className="modal" onClick={event => event.stopPropagation()} onSubmit={create}><div className="pane-head"><div><p className="eyebrow">User management</p><h2>Create local user</h2></div><button type="button" className="icon-action" onClick={() => setShowCreate(false)}>×</button></div><div className="field-grid"><Field label="Name" value={form.name} onChange={value => setForm({ ...form, name: value })} /><Field label="Email" value={form.email} onChange={value => setForm({ ...form, email: value })} /><Field label="Temporary password" value={form.password} onChange={value => setForm({ ...form, password: value })} hint="At least 12 characters" /><div className="field"><span>Role</span><AdminSelect value={form.role} options={roleOptions} ariaLabel="Role" onChange={value => setForm({ ...form, role: value })} /></div></div><div className="save-rail"><span>Password reset will be required on first sign-in.</span><button className="primary-action compact">Create user <span>→</span></button></div></form></div>}</div>;
}

function Metric({ value, label }: { value: string; label: string }) { return <div className="metric"><strong>{value}</strong><span>{label}</span></div>; }

function IdentitySettings({ setNotice, user }: { setNotice: (value: string) => void; user: User }) {
  const [localEnabled, setLocalEnabled] = useState(true); const [entraEnabled, setEntraEnabled] = useState(false); const [identities, setIdentities] = useState<any[]>([]); const [entraForm, setEntraForm] = useState({ providerId: "", email: "", displayName: "", role: "Viewer" as Role }); const canManage = user.role === "Super Admin" || user.role === "User Manager";
  useEffect(() => { api("/api/v1/admin/settings/identity").then(response => response.json()).then(payload => { setLocalEnabled(payload.data.localEnabled); setEntraEnabled(payload.data.entraEnabled); }); api("/api/v1/admin/identities").then(response => response.json()).then(payload => setIdentities(payload.data || [])); }, []);
  const save = async () => { if (!localEnabled && !entraEnabled) { setNotice("At least one provider must remain enabled"); return; } const response = await api("/api/v1/admin/settings/identity", { method: "PUT", body: JSON.stringify({ localEnabled, entraEnabled, confirmation: true }) }); setNotice(response.ok ? "Identity settings saved" : "Identity settings could not be changed"); };
  const addIdentity = async (event: React.FormEvent) => { event.preventDefault(); const response = await api("/api/v1/admin/identities", { method: "POST", body: JSON.stringify(entraForm) }); if (response.ok) { const payload = await response.json(); setIdentities(rows => [payload.data, ...rows]); setNotice("Explicit Entra access added"); setEntraForm({ providerId: "", email: "", displayName: "", role: "Viewer" }); } else setNotice("Entra identity could not be added"); };
  return <div className="workspace identity-workspace"><div className="workspace-intro"><div><p className="eyebrow">Authentication policy</p><h2>Make access deliberate.</h2><p>Providers can be changed only by a Super Admin. An Entra directory user receives no application access until explicitly added here.</p></div><button className="primary-action compact" onClick={() => void save()} disabled={!canManage}>Save policy <span>→</span></button></div><div className="identity-grid"><section className="policy-panel"><div className="panel-title"><span className="panel-icon">⌁</span><div><h3>Sign-in providers</h3><p>Keep at least one valid Super Admin path active.</p></div></div><Toggle label="Local authentication" detail="Email and password with reset support" value={localEnabled} setValue={setLocalEnabled} /><Toggle label="Microsoft Entra ID" detail="OIDC / MSAL server-side integration" value={entraEnabled} setValue={setEntraEnabled} /></section><section className="policy-panel"><div className="panel-title"><span className="panel-icon">◎</span><div><h3>Explicit Entra access</h3><p>Least-privilege assignment, never implicit tenant access.</p></div></div><form onSubmit={addIdentity} className="field-grid"><Field label="Directory object ID" value={entraForm.providerId} onChange={value => setEntraForm({ ...entraForm, providerId: value })} /><Field label="Work email" value={entraForm.email} onChange={value => setEntraForm({ ...entraForm, email: value })} /><Field label="Display name" value={entraForm.displayName} onChange={value => setEntraForm({ ...entraForm, displayName: value })} /><div className="field"><span>Application role</span><AdminSelect value={entraForm.role} options={roleOptions} ariaLabel="Application role" onChange={value => setEntraForm({ ...entraForm, role: value })} /></div><button className="secondary-action" disabled={!canManage || !entraEnabled}>Add selected user</button></form><p className="integration-note">Tenant directory search becomes available when Microsoft Graph credentials are configured server-side. Tokens are never sent to the browser.</p></section></div><section className="identity-list"><div className="panel-title"><span className="panel-icon">◌</span><div><h3>Added identities</h3><p>{identities.length ? "Only these directory users can enter the application." : "No Entra users have been added yet."}</p></div></div>{identities.map(identity => <div className="identity-row" key={identity.id}><span className="avatar">{identity.displayName.slice(0, 1)}</span><span><strong>{identity.displayName}</strong><small>{identity.email} · {identity.role}</small></span><span className="status-tag published">Explicit access</span></div>)}</section></div>;
}
function Toggle({ label, detail, value, setValue }: { label: string; detail: string; value: boolean; setValue: (value: boolean) => void }) { return <button className="toggle-row" onClick={() => setValue(!value)}><span><strong>{label}</strong><small>{detail}</small></span><i className={value ? "on" : ""}><b /></i></button>; }
type IntegrationState = {
  smtp: { configured: boolean; host: string; port: number; secure: boolean; username: string; senderName: string; senderEmail: string; testRecipient: string; passwordConfigured: boolean };
  newsletter: { enabled: boolean; provider: string; endpoint: string; listId: string; apiKeyConfigured: boolean };
  recaptcha: { enabled: boolean; siteKey: string; protectedPaths: string[] };
  redis: { enabled: boolean; configured: boolean; url: string; username: string; database: number; passwordConfigured: boolean };
  updatedAt: string | null;
};

const componentStatusLabel = (status: string) => status === "current" ? "Current" : status === "outdated" ? "Update available" : status === "missing" ? "Missing" : "Not checked";
const componentStatusClass = (status: string) => status === "current" ? "published" : status === "outdated" ? "draft" : status === "missing" ? "archived" : "unknown";
type SettingsSection = "assistant" | "branding" | "integrations" | "components" | "identity";
type BrandMediaKey = "mark" | "markLight" | "markDark" | "wordmark" | "wordmarkLight" | "wordmarkDark";

function SettingsWorkspace({ setNotice, user }: { setNotice: (value: string) => void; user: User }) {
  const [settings, setSettings] = useState<IntegrationState | null>(null);
  const [assistant, setAssistant] = useState<AssistantSettings | null>(null);
  const [brand, setBrand] = useState<BrandSettings | null>(null);
  const [footer, setFooter] = useState<FooterContent | null>(null);
  const [activeSettings, setActiveSettings] = useState<SettingsSection>("assistant");
  const [components, setComponents] = useState<any[]>([]);
  const [checkingComponents, setCheckingComponents] = useState(false);
  const [resettingCache, setResettingCache] = useState(false);
  const [smtpPassword, setSmtpPassword] = useState("");
  const [newsletterKey, setNewsletterKey] = useState("");
  const [recaptchaSecret, setRecaptchaSecret] = useState("");
  const [redisPassword, setRedisPassword] = useState("");
  const canManage = user.role === "Super Admin";
  const recheckComponents = async () => { setCheckingComponents(true); try { const response = await api("/api/v1/admin/system/components"); if (!response.ok) throw new Error(); const payload = await response.json(); setComponents(payload.data?.packages || []); setNotice("Component versions rechecked"); } catch { setNotice("Component version check could not reach the registry"); } finally { setCheckingComponents(false); } };
  const resetPublicCache = async () => { if (!canManage || resettingCache) return; setResettingCache(true); setNotice("Resetting public cache…"); try { const response = await api("/api/v1/admin/settings/cache/reset", { method: "POST" }); const payload = await response.json() as { data?: { cleared?: boolean } }; if (!response.ok) { setNotice("Public cache could not be reset"); return; } setNotice(payload.data?.cleared ? "Public cache reset · next public read will refresh" : "No active Redis cache found · public reads will use the source of truth"); } catch { setNotice("Public cache could not be reset"); } finally { setResettingCache(false); } };
  useEffect(() => { api("/api/v1/admin/settings/integrations").then(response => response.ok ? response.json() : Promise.reject()).then(payload => setSettings(payload.data)).catch(() => setNotice("Integration settings could not be loaded")); api("/api/v1/admin/settings/assistant").then(response => response.ok ? response.json() : Promise.reject()).then(payload => setAssistant(payload.data)).catch(() => setNotice("Assistant settings could not be loaded")); api("/api/v1/admin/settings/brand").then(response => response.ok ? response.json() : Promise.reject()).then(payload => setBrand(payload.data)).catch(() => setNotice("Brand settings could not be loaded")); api("/api/v1/admin/settings/footer").then(response => response.ok ? response.json() : Promise.reject()).then(payload => setFooter(payload.data)).catch(() => setNotice("Footer settings could not be loaded")); void recheckComponents(); }, [setNotice]);
  if (!settings || !assistant || !brand || !footer) return <div className="workspace-loading">Loading system settings…</div>;
  const save = async (section: string, value: Record<string, unknown>) => { if (!canManage) return; const response = await api("/api/v1/admin/settings/integrations", { method: "PUT", body: JSON.stringify({ [section]: value }) }); if (!response.ok) { setNotice("Settings could not be saved. Configure INTEGRATION_SECRET_KEY first."); return; } setSettings((await response.json()).data); setNotice(`${section[0].toUpperCase()}${section.slice(1)} settings saved`); if (section === "smtp") setSmtpPassword(""); if (section === "newsletter") setNewsletterKey(""); if (section === "recaptcha") setRecaptchaSecret(""); if (section === "redis") setRedisPassword(""); };
  const saveAssistant = async () => { if (!canManage) return; const response = await api("/api/v1/admin/settings/assistant", { method: "PUT", body: JSON.stringify(assistant) }); if (!response.ok) { setNotice("Assistant settings could not be saved"); return; } setAssistant((await response.json()).data); setNotice("Ask MOVERA assistant settings saved"); };
  const saveBrand = async () => { if (!canManage) return; const response = await api("/api/v1/admin/settings/brand", { method: "PUT", body: JSON.stringify(brand) }); if (!response.ok) { setNotice("Brand settings could not be saved"); return; } setBrand((await response.json()).data); setNotice("Brand settings saved"); };
  const saveFooter = async () => { if (!canManage) return; const response = await api("/api/v1/admin/settings/footer", { method: "PUT", body: JSON.stringify(footer) }); if (!response.ok) { setNotice("Footer social links could not be saved"); return; } setFooter((await response.json()).data); setNotice("Footer social links saved"); };
  const uploadAssistant = async (file: File) => { const form = new FormData(); form.append("file", file); setNotice("Uploading assistant image…"); const response = await api("/api/v1/media", { method: "POST", body: form }); const payload = await response.json(); if (!response.ok) { setNotice("Assistant image upload failed"); return; } setAssistant(current => current ? { ...current, icon: { ...current.icon, id: payload.data.id, url: payload.data.url } } : current); setNotice("Assistant image uploaded · save settings to apply it"); };
  const uploadBrand = async (key: BrandMediaKey, file: File) => { const form = new FormData(); form.append("file", file); setNotice(`Uploading ${key}…`); const response = await api("/api/v1/media", { method: "POST", body: form }); const payload = await response.json(); if (!response.ok) { setNotice(`${key} upload failed`); return; } setBrand(current => { if (!current) return current; const fallback = key.toLowerCase().includes("wordmark") ? current.wordmark : current.mark; return { ...current, [key]: { ...(current[key] || fallback), id: payload.data.id, url: payload.data.url } }; }); setNotice(`${key} uploaded · save brand settings to apply it`); };
  const test = async (kind: "smtp" | "newsletter" | "redis", recipient?: string) => { const path = kind === "smtp" ? "smtp" : kind === "newsletter" ? "newsletter" : "redis"; const response = await api(`/api/v1/admin/settings/integrations/${path}/test`, { method: "POST", body: recipient ? JSON.stringify({ recipient }) : JSON.stringify({}) }); setNotice(response.ok ? `${kind[0].toUpperCase()}${kind.slice(1)} test succeeded` : `${kind[0].toUpperCase()}${kind.slice(1)} test failed`); };
  const update = <K extends keyof IntegrationState>(key: K, value: IntegrationState[K]) => setSettings(current => current ? { ...current, [key]: value } : current);
  return <div className="workspace settings-workspace" data-active-settings={activeSettings}><div className="workspace-intro"><div><p className="eyebrow">Operational settings</p><h2>Connect the services around the site.</h2><p>Secrets are write-only in this interface. The approved public design and content renderer remain locked.</p></div><span className="locked-pill">Super Admin only</span></div><div className="settings-subnav" role="tablist">{([['assistant', 'Ask MOVERA'], ['branding', 'Branding'], ['integrations', 'Integrations'], ['components', 'System components'], ['identity', 'Identity & Login']] as const).map(([key, label]) => <button type="button" role="tab" aria-selected={activeSettings === key} className={activeSettings === key ? "active" : ""} onClick={() => setActiveSettings(key)} key={key}>{label}</button>)}</div>
    <section className="settings-panel"><div className="panel-title"><span className="panel-icon">✦</span><div><h3>Ask MOVERA assistant</h3><p>Choose the icon and label used by the public assistant trigger and chat panel.</p></div></div><div className="settings-form-grid"><Field label="Assistant label · English" value={assistant.label.en} onChange={value => setAssistant({ ...assistant, label: { ...assistant.label, en: value } })} /><Field label="Assistant label · العربية" value={assistant.label.ar} onChange={value => setAssistant({ ...assistant, label: { ...assistant.label, ar: value } })} /><Field label="Assistant label · Français" value={assistant.label.fr} onChange={value => setAssistant({ ...assistant, label: { ...assistant.label, fr: value } })} /><Field label="Assistant label · Nederlands" value={assistant.label.nl} onChange={value => setAssistant({ ...assistant, label: { ...assistant.label, nl: value } })} /></div><MediaSlotEditor label="Assistant icon" locale="en" media={assistant.icon} fallback={`${PUBLIC}/starter-media/assistant.svg`} onChange={icon => icon && setAssistant({ ...assistant, icon })} onUpload={uploadAssistant} /><div className="setting-actions"><button className="primary-action compact" onClick={() => void saveAssistant()} disabled={!canManage}>Save assistant settings <span>→</span></button></div></section>
    <BrandingSettingsPanel brand={brand} setBrand={next => setBrand(next)} uploadBrand={uploadBrand} saveBrand={saveBrand} footer={footer} setFooter={next => setFooter(next)} saveFooter={saveFooter} canManage={canManage} />
    <section className="settings-panel"><div className="panel-title"><span className="panel-icon">✉</span><div><h3>SMTP delivery</h3><p>Configure sender details and send a real verification message.</p></div></div><div className="settings-form-grid"><Field label="SMTP host" value={settings.smtp.host} onChange={value => update("smtp", { ...settings.smtp, host: value })} /><Field label="Port" value={String(settings.smtp.port)} onChange={value => update("smtp", { ...settings.smtp, port: Number(value) || 587 })} /><Field label="Username" value={settings.smtp.username} onChange={value => update("smtp", { ...settings.smtp, username: value })} /><Field label="Password" value={smtpPassword} onChange={setSmtpPassword} hint={settings.smtp.passwordConfigured ? "Configured; enter a new value only to replace it." : "Stored securely and never displayed."} /><Field label="Sender name" value={settings.smtp.senderName} onChange={value => update("smtp", { ...settings.smtp, senderName: value })} /><Field label="Sender email" value={settings.smtp.senderEmail} onChange={value => update("smtp", { ...settings.smtp, senderEmail: value })} /><Field label="Test recipient" value={settings.smtp.testRecipient} onChange={value => update("smtp", { ...settings.smtp, testRecipient: value })} /></div><label className="setting-check"><input type="checkbox" checked={settings.smtp.secure} onChange={event => update("smtp", { ...settings.smtp, secure: event.target.checked })} />Use TLS / secure transport</label><div className="setting-actions"><button className="secondary-action" onClick={() => void save("smtp", { ...settings.smtp, password: smtpPassword || undefined })} disabled={!canManage}>Save SMTP</button><button className="primary-action compact" onClick={() => void test("smtp", settings.smtp.testRecipient)}>Test SMTP <span>→</span></button></div></section>
    <section className="settings-panel"><div className="panel-title"><span className="panel-icon">✦</span><div><h3>Newsletter connector</h3><p>Forward captured subscriptions to the configured external platform.</p></div></div><div className="settings-form-grid"><Field label="Provider" value={settings.newsletter.provider} onChange={value => update("newsletter", { ...settings.newsletter, provider: value })} /><Field label="Endpoint" value={settings.newsletter.endpoint} onChange={value => update("newsletter", { ...settings.newsletter, endpoint: value })} hint="HTTPS is required in production." /><Field label="List / audience ID" value={settings.newsletter.listId} onChange={value => update("newsletter", { ...settings.newsletter, listId: value })} /><Field label="API key" value={newsletterKey} onChange={setNewsletterKey} hint={settings.newsletter.apiKeyConfigured ? "Configured; enter a new value only to replace it." : "Stored securely and never displayed."} /><Field label="Test recipient" value={settings.smtp.testRecipient} onChange={value => update("smtp", { ...settings.smtp, testRecipient: value })} /></div><label className="setting-check"><input type="checkbox" checked={settings.newsletter.enabled} onChange={event => update("newsletter", { ...settings.newsletter, enabled: event.target.checked })} />Enable forwarding after local capture</label><div className="setting-actions"><button className="secondary-action" onClick={() => void save("newsletter", { ...settings.newsletter, apiKey: newsletterKey || undefined })} disabled={!canManage}>Save newsletter</button><button className="primary-action compact" onClick={() => void test("newsletter", settings.smtp.testRecipient)}>Test connector <span>→</span></button></div></section>
    <section className="settings-panel"><div className="panel-title"><span className="panel-icon">◎</span><div><h3>Invisible Google reCAPTCHA</h3><p>Protect only selected public forms. Google remains the explicit external exception.</p></div></div><div className="settings-form-grid"><Field label="Site key" value={settings.recaptcha.siteKey} onChange={value => update("recaptcha", { ...settings.recaptcha, siteKey: value })} /><Field label="Secret key" value={recaptchaSecret} onChange={setRecaptchaSecret} hint="Stored securely and never displayed." /></div><label className="setting-check"><input type="checkbox" checked={settings.recaptcha.enabled} onChange={event => update("recaptcha", { ...settings.recaptcha, enabled: event.target.checked })} />Enable verification</label><div className="protected-paths"><span className="field-label">Protected public forms</span>{["homepage", "contact", "newsletter", "careers", "chat"].map(path => <label key={path}><input type="checkbox" checked={settings.recaptcha.protectedPaths.includes(path)} onChange={event => update("recaptcha", { ...settings.recaptcha, protectedPaths: event.target.checked ? [...settings.recaptcha.protectedPaths, path] : settings.recaptcha.protectedPaths.filter(item => item !== path) })} />{path}</label>)}</div><div className="setting-actions"><button className="primary-action compact" onClick={() => void save("recaptcha", { ...settings.recaptcha, secretKey: recaptchaSecret || undefined })} disabled={!canManage}>Save reCAPTCHA <span>→</span></button></div></section>
    <section className="settings-panel"><div className="panel-title"><span className="panel-icon">◌</span><div><h3>Redis cache</h3><p>PostgreSQL remains the source of truth; Redis is optional acceleration.</p></div></div><div className="settings-form-grid"><Field label="Redis URL" value={settings.redis.url} onChange={value => update("redis", { ...settings.redis, url: value })} /><Field label="Username" value={settings.redis.username} onChange={value => update("redis", { ...settings.redis, username: value })} /><Field label="Password" value={redisPassword} onChange={setRedisPassword} hint={settings.redis.passwordConfigured ? "Configured; enter a new value only to replace it." : "Stored securely and never displayed."} /><Field label="Database number" value={String(settings.redis.database)} onChange={value => update("redis", { ...settings.redis, database: Number(value) || 0 })} /></div><label className="setting-check"><input type="checkbox" checked={settings.redis.enabled} onChange={event => update("redis", { ...settings.redis, enabled: event.target.checked })} />Enable Redis</label><div className="setting-actions"><button className="secondary-action" onClick={() => void save("redis", { ...settings.redis, password: redisPassword || undefined })} disabled={!canManage}>Save Redis</button><button className="primary-action compact" onClick={() => void test("redis")}>Test Redis <span>→</span></button><button className="secondary-action" onClick={() => void resetPublicCache()} disabled={!canManage || resettingCache}>{resettingCache ? "Resetting…" : "Reset public cache"}</button></div></section>
    <section className="settings-panel components-panel"><div className="panel-title"><span className="panel-icon">▦</span><div><h3>System components</h3><p>Installed versions are read locally. Latest-version checks are informational and only run when the registry is reachable.</p></div><button className="secondary-action compact" onClick={() => void recheckComponents()} disabled={checkingComponents}>{checkingComponents ? "Checking…" : "Recheck versions"}</button></div><div className="component-table"><div className="component-row component-head"><span>Component</span><span>Declared</span><span>Installed</span><span>Latest</span><span>Status</span></div>{components.map(component => <div className="component-row" key={component.name}><span>{component.name}</span><span>{component.declared}</span><span>{component.installed || "Missing"}</span><span>{component.latest || "Not checked"}</span><span className={`status-tag ${componentStatusClass(component.status)}`}>{componentStatusLabel(component.status)}</span></div>)}</div><p className="integration-note">“Not checked” means registry metadata was unavailable; it is not an outdated or vulnerable status. Local assets and system fonts are used by default.</p></section>
    {activeSettings === "identity" && <IdentitySettings setNotice={setNotice} user={user} />}
  </div>;
}
